        function showDetails(name) {

            var data =
                descriptions[name];


            if (!data) {
                return;
            }


            var steps =
                isArabic
                    ? data.stepsAr
                    : data.stepsEn;


            var list = "";


            for (
                var i = 0;
                i < steps.length;
                i++
            ) {

                list +=

                    "<li>" +
                    escapeHtml(
                        steps[i]
                    ) +
                    "</li>";

            }


            var overlay =
                document.createElement(
                    "div"
                );


            overlay.className =
                "erp-modal-overlay";


            overlay.setAttribute(
                "dir",
                isArabic ? "rtl" : "ltr"
            );


            overlay.innerHTML =

                '<div class="erp-modal-box">' +

                    '<button class="erp-modal-close" data-buy-modal-close>✕</button>' +

                    '<div class="erp-modal-header">' +

                        '<span class="erp-modal-icon">📄</span>' +

                        '<h3 class="erp-modal-title">' +

                            escapeHtml(
                                text(
                                    data.titleAr,
                                    data.titleEn
                                )
                            ) +

                        '</h3>' +

                    '</div>' +

                    '<p class="erp-modal-summary">' +

                        escapeHtml(
                            text(
                                data.summaryAr,
                                data.summaryEn
                            )
                        ) +

                    '</p>' +

                    '<button class="erp-modal-toggle-steps" data-buy-show-steps>' +

                        text(
                            "📖 عرض الخطوات",
                            "📖 Show Steps"
                        ) +

                    '</button>' +

                    '<div class="erp-modal-steps" data-buy-steps>' +

                        '<ol class="erp-modal-steps-list">' +
                            list +
                        '</ol>' +

                    '</div>' +

                '</div>';


            root.appendChild(
                overlay
            );


            setTimeout(
                function () {
                    overlay.classList.add(
                        "is-visible"
                    );
                },
                10
            );


            var close =
                overlay.querySelector(
                    "[data-buy-modal-close]"
                );


            if (close) {

                close.addEventListener(
                    "click",
                    function () {
                        overlay.remove();
                    }
                );

            }


            var toggle =
                overlay.querySelector(
                    "[data-buy-show-steps]"
                );


            var box =
                overlay.querySelector(
                    "[data-buy-steps]"
                );


            if (
                toggle &&
                box
            ) {

                toggle.addEventListener(
                    "click",
                    function () {

                        box.classList.toggle(
                            "is-shown"
                        );

                    }
                );

            }

        }


