          });

        })
    },


    /* قيمة المخزون */
    {
      id: "stock-value",

      short: "VAL",

      labelEn: "Stock Value",
      labelAr: "قيمة المخزون",

      isCurrency: true,

      fetch: async () => {

        const rows =
          await getStockBalance();

        let total = 0;

        rows.forEach(row => {

          total +=
            Number(
              row.bal_val ??
              row.stock_value ??
