      fetch: async () => {

        /*
          يعتمد على الكمية المتاحة.
          نعتبر الكمية <= 0 منخفضة بشكل مباشر.
          ويمكن لاحقاً ربطها بمستوى إعادة الطلب لكل مستودع.
        */

        const rows =
