        "أدخل الكمية الفعلية",
        "راجع سعر التقييم",
        "اضغط «حفظ» ثم «تسجيل»"

      ],

      stepsEn: [

        "Click «New Stock Reconciliation»",
        "Select company",
        "Set posting date and time",
        "Add items and warehouses",
        "Enter physical quantity",
        "Review valuation rate",
        "Click «Save» then «Submit»"

      ]

    },


    "Item": {

      icon: "🏷️",

      summaryAr:
        "تعريف الصنف وخصائص المخزون ووحدة القياس والتسعير والتتبع.",

      summaryEn:
        "Define item details, inventory settings, UOM, pricing, and tracking.",

      stepsAr: [

        "اضغط «صنف جديد»",
        "أدخل رمز واسم الصنف",
        "اختر مجموعة الأصناف",
        "حدد وحدة القياس",
        "فعّل الاحتفاظ بالمخزون",
        "حدد إعدادات المستودع",
        "اضغط «حفظ»"

      ],

      stepsEn: [

        "Click «New Item»",
        "Enter item code and name",
        "Select item group",
        "Set stock UOM",
        "Enable Maintain Stock",
        "Set inventory defaults",
        "Click «Save»"

      ]

    },


    "Warehouse": {

      icon: "🏢",

      summaryAr:
        "تعريف مستودعات الشركة وتنظيمها بشكل هرمي.",

      summaryEn:
        "Define and organize company warehouses in a hierarchical structure.",

      stepsAr: [

        "افتح «المستودعات»",
        "اختر المستودع الأب",
        "أضف مستودعاً جديداً",
        "حدد الشركة",
        "أدخل اسم المستودع",
        "اضغط «حفظ»"

      ],

      stepsEn: [

        "Open «Warehouse»",
        "Select parent warehouse",
        "Add a new warehouse",
        "Select company",
        "Enter warehouse name",
        "Click «Save»"

      ]

    },


    "Serial No": {

      icon: "🔢",

      summaryAr:
        "متابعة كل وحدة مخزنية بواسطة رقم تسلسلي فريد.",

      summaryEn:
        "Track individual stock units using unique serial numbers.",

      stepsAr: [

        "فعّل الرقم التسلسلي في بطاقة الصنف",
        "حدد سلسلة الأرقام عند الحاجة",
        "استخدم الصنف في حركة المخزون",
        "سيتم تسجيل الرقم التسلسلي مع الحركة"

      ],

      stepsEn: [

        "Enable serial number tracking in Item",
        "Set serial number series if required",
        "Use the item in a stock transaction",
        "Serial numbers will be recorded with the transaction"

      ]

    },


    "Batch": {

      icon: "📦",

      summaryAr:
        "إدارة الأصناف حسب الدفعات وتواريخ الإنتاج والانتهاء.",

      summaryEn:
        "Manage inventory by batches with manufacturing and expiry dates.",

      stepsAr: [

        "فعّل تتبع الدفعات في الصنف",
        "حدد إعدادات إنشاء الدفعة",
        "أدخل تاريخ الانتهاء عند الحاجة",
        "استخدم رقم الدفعة في حركات المخزون"

      ],

      stepsEn: [

        "Enable batch tracking in Item",
        "Configure batch creation",
        "Set expiry date if required",
        "Use batch number in stock transactions"

      ]

    }

  };


  /* =========================================================
     11. HELPERS
  ========================================================= */

  function translate(name) {

    if (!isArabic)
      return name;

    return (
      arabicFallback[name] ||
      (
        typeof window.__ === "function"
          ? window.__(name)
          : name
      )
    );

  }


  function escapeHtml(value) {

    return String(value ?? "")

      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");

  }


  function formatNumber(number) {

    return (
      parseFloat(number) || 0
    ).toLocaleString("en-US");

  }


  function formatCurrency(number) {

    return (
      parseFloat(number) || 0
    ).toLocaleString(
       "en-US",
      {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }
    );

  }


  /* =========================================================
     12. MODAL
  ========================================================= */

  function showInfoModal(data) {

    const title =
      isArabic
        ? data.labelAr
        : data.labelEn;

    const summary =
      isArabic
        ? data.summaryAr
        : data.summaryEn;

    const steps =
      isArabic
        ? data.stepsAr
        : data.stepsEn;

    const hasSteps =
      Array.isArray(steps) &&
      steps.length > 0;

    const showText =
      isArabic
        ? "📖 عرض الخطوات"
        : "📖 Show Steps";

    const hideText =
      isArabic
        ? "📖 إخفاء الخطوات"
        : "📖 Hide Steps";


    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-modal-close
        >
          ✕
        </button>


        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            ${data.icon || "📄"}
          </span>

          <h3 class="erp-modal-title">
            ${escapeHtml(title)}
          </h3>

        </div>


        <p class="erp-modal-summary">
          ${escapeHtml(summary)}
        </p>


        ${
          hasSteps
            ? `
              <button
                type="button"
                class="erp-modal-toggle-steps"
                data-toggle-steps
              >
                ${showText}
              </button>

              <div
                class="erp-modal-steps"
                data-modal-steps
              >

                <ol class="erp-modal-steps-list">

                  ${steps
                    .map(
                      step =>
                        `<li>${escapeHtml(step)}</li>`
                    )
                    .join("")}

                </ol>

              </div>
            `
            : ""
        }

      </div>

    `;


    root.appendChild(overlay);


    requestAnimationFrame(() => {

      overlay.classList.add(
        "is-visible"
      );

    });


    function closeModal() {

      overlay.remove();

    }


    overlay
      .querySelector("[data-modal-close]")
      ?.addEventListener(
        "click",
        closeModal
      );


    overlay.addEventListener(

      "click",

      event => {

        if (event.target === overlay)
          closeModal();

      }

    );


    const toggleButton =
      overlay.querySelector(
        "[data-toggle-steps]"
      );

    const stepsContainer =
      overlay.querySelector(
        "[data-modal-steps]"
      );


    if (
      toggleButton &&
      stepsContainer
    ) {

      toggleButton.addEventListener(

        "click",

        () => {

          stepsContainer.classList.toggle(
            "is-shown"
          );

          toggleButton.textContent =
            stepsContainer.classList.contains(
              "is-shown"
            )
              ? hideText
              : showText;

        }

      );

    }

  }


  /* =========================================================
     13. ROUTING
  ========================================================= */

  function openRoute(name) {

    if (
      !window.frappe ||
      typeof frappe.set_route !== "function"
    )
      return;


    if (reportNames.has(name)) {

      frappe.set_route(
        "query-report",
        name
      );

      return;

    }


    if (singleDocs.has(name)) {

      frappe.set_route(
        "Form",
        name
      );

      return;

    }


    if (treeDocs.has(name)) {

      frappe.set_route(
        "Tree",
        name
      );

      return;

    }


    frappe.set_route(
      "List",
      name
    );

  }


  /* =========================================================
     14. RENDER STOCK CYCLE
  ========================================================= */

  function renderStockCycle() {

    if (!stockCycle)
      return;


    const sectionTitle =
      isArabic
        ? "دورة المخزون"
        : "Stock Cycle";


    stockCycle.innerHTML = `

      <section class="erp-cycle-container">

        <h2 class="erp-section-title erp-cycle-title">
          ${escapeHtml(sectionTitle)}
        </h2>


        <div
          class="erp-cycle-grid"
          style="
            grid-template-columns:
            repeat(
              ${stockCycleCards.length},
              minmax(0, 1fr)
            );
          "
        >

          ${stockCycleCards

            .map(
              (card, index) => {

                const title =
                  isArabic
                    ? card.labelAr
                    : card.labelEn;

                const description =
                  isArabic
                    ? card.descriptionAr
                    : card.descriptionEn;


                const arrow =
                  index <
                  stockCycleCards.length - 1

                    ? `
                      <span
                        class="erp-cycle-arrow"
                        aria-hidden="true"
                      >
                        ${isArabic ? "←" : "→"}
                      </span>
                    `
                    : "";


                return `

                  <div class="erp-cycle-item">

                    <button
                      type="button"
                      class="
                        erp-cycle-card
                        cycle-tone-${(index % 4) + 1}
                      "
                      data-cycle-index="${index}"
                    >

                      <span class="erp-cycle-number">
                        ${card.step}
                      </span>

                      <span class="erp-cycle-card-title">
                        ${escapeHtml(title)}
                      </span>

                      <span class="erp-cycle-description">
                        ${escapeHtml(description)}
                      </span>

                    </button>

                    ${arrow}

                  </div>

                `;

              }
            )

            .join("")}

        </div>

      </section>

    `;


    stockCycle.addEventListener(

      "click",

      event => {

        const element =
          event.target.closest(
            "[data-cycle-index]"
          );

        if (!element)
          return;


        const card =
          stockCycleCards[
            Number(
              element.dataset.cycleIndex
            )
          ];

        if (!card)
          return;


        if (
          card.doctype === "Stock Entry" &&
          card.stockEntryType
        ) {

          frappe.new_doc(
            "Stock Entry",
            {
              stock_entry_type:
                card.stockEntryType
            }
          );

          return;

        }


        openRoute(
          card.doctype
        );

      }

    );

  }


  /* =========================================================
     15. RENDER STATS
  ========================================================= */

  function renderStats() {

    if (!statsSection)
      return;


    statsSection.innerHTML = `

      <section class="erp-overview-container">

        <h2 class="erp-section-title">

          ${escapeHtml(
            isArabic
              ? "نظرة عامة"
              : "Overview"
          )}

        </h2>


        <div class="erp-stats-grid">

          ${statsCards

            .map(
              (card, index) => `

                <div
                  class="
                    erp-stat-card
                    overview-tone-${index + 1}
                  "
                >

                  <div class="erp-stat-icon">
                    ${escapeHtml(card.short)}
                  </div>


                  <div class="erp-stat-info">

                    <span
                      class="erp-stat-value"
                      data-stat-id="${card.id}"
                    >
                      ...
                    </span>

                    <span class="erp-stat-label">

                      ${escapeHtml(
                        isArabic
                          ? card.labelAr
                          : card.labelEn
                      )}

                    </span>

                  </div>

                </div>

              `
            )

            .join("")}

        </div>

      </section>

    `;


    statsCards.forEach(card => {

      card.fetch().then(value => {

        const element =
          statsSection.querySelector(
            `[data-stat-id="${card.id}"]`
          );

        if (!element)
          return;


        element.textContent =
          card.isCurrency

            ? `${formatCurrency(value)} ${
                isArabic ? "ر.س" : "SAR"
              }`

            : formatNumber(value);

      });

    });

  }


  /* =========================================================
     16. QUICK ACTIONS
  ========================================================= */

  function renderQuickActions() {

    if (!quickActions)
      return;


    quickActions.innerHTML = `

      <h2 class="erp-section-title">

        ${
          isArabic
            ? "اختصارات سريعة"
            : "Quick Actions"
        }

      </h2>


      <div class="erp-quick-grid">

        ${quickActionButtons

          .map(
            (button, index) => `

              <button
                type="button"
                class="erp-quick-btn"
                data-quick-index="${index}"
              >

                <span class="erp-quick-label">

                  ${escapeHtml(
                    isArabic
                      ? button.labelAr
                      : button.labelEn
                  )}

                </span>

              </button>

            `
          )

          .join("")}

      </div>

    `;


    quickActions.addEventListener(

      "click",

      event => {

        const element =
          event.target.closest(
            "[data-quick-index]"
          );

        if (!element)
          return;


        const button =
          quickActionButtons[
            Number(
              element.dataset.quickIndex
            )
          ];

        if (!button)
          return;


        const defaults = {};

        if (button.stockEntryType) {

          defaults.stock_entry_type =
            button.stockEntryType;

        }


        frappe.new_doc(
          button.doctype,
          defaults
        );

      }

    );

  }


  /* =========================================================
     17. SECTIONS
  ========================================================= */

  function renderSections() {

    content.innerHTML =
      sections

        .map(
          (section, sectionIndex) => {


            const cards =
              section[1]

                .map(
                  (card, cardIndex) => {


                    const links =
                      card[2]

                        .map(
                          item => {


                            const description =
                              itemDescriptions[item];


                            return `

                              <div class="erp-link-row">

                                <button
                                  type="button"
                                  class="erp-link"
                                  data-route-name="${escapeHtml(item)}"
                                >

                                  <span class="erp-link-text">
                                    ${escapeHtml(translate(item))}
                                  </span>

                                  <span class="erp-link-arrow">
                                    ${isArabic ? "←" : "→"}
                                  </span>

                                </button>


                                ${
                                  description
                                    ? `
                                      <button
                                        type="button"
                                        class="erp-info-link"
                                        data-info-item="${escapeHtml(item)}"
                                      >
                                        ${isArabic ? "تفاصيل" : "Details"}
                                      </button>
                                    `
                                    : ""
                                }

                              </div>

                            `;

                          }
                        )

                        .join("");


                    return `

                      <article
                        class="
                          erp-card
                          tone-${(sectionIndex + cardIndex) % 5}
                        "
                        data-erp-card
                      >

                        <button
                          type="button"
                          class="erp-card-heading"
                          data-card-toggle
                          aria-expanded="false"
                        >

                          <span class="erp-icon">
                            ${card[1]}
                          </span>

                          <span class="erp-card-title">
                            ${escapeHtml(translate(card[0]))}
                          </span>

                          <span class="erp-card-chevron">
                            ⌄
                          </span>

                        </button>


                        <div class="erp-card-links">
                          ${links}
                        </div>

                      </article>

                    `;

                  }
                )

                .join("");


            return `

              <section class="erp-module-section">

                <h2 class="erp-section-title">
                  ${escapeHtml(translate(section[0]))}
                </h2>

                <div class="erp-dashboard-grid">
                  ${cards}
                </div>

              </section>

            `;

          }
        )

        .join("");

  }


  /* =========================================================
     18. FOOTER
  ========================================================= */

  function renderFooter() {

    if (!footerEl)
      return;


    footerEl.innerHTML = `

      <div class="erp-footer-inner">

        <div class="erp-footer-item">

          <span class="erp-footer-icon">☎</span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? footerInfo.labels.phoneAr
                : footerInfo.labels.phoneEn
            }:

          </span>

          <a
            href="tel:${footerInfo.phone}"
            class="erp-footer-link"
            dir="ltr"
          >
            ${footerInfo.phone}
          </a>

        </div>


        <span class="erp-footer-sep">|</span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">✉</span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? footerInfo.labels.emailAr
                : footerInfo.labels.emailEn
            }:

          </span>

          <a
            href="mailto:${footerInfo.email}"
            class="erp-footer-link"
          >
            ${footerInfo.email}
          </a>

        </div>


        <span class="erp-footer-sep">|</span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">◎</span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? footerInfo.labels.websiteAr
                : footerInfo.labels.websiteEn
            }:

          </span>

          <a
            href="https://${footerInfo.website}"
            class="erp-footer-link"
            target="_blank"
          >
            ${footerInfo.website}
          </a>

        </div>

      </div>

    `;

  }


  /* =========================================================
     19. EVENTS
  ========================================================= */

  content.addEventListener(

    "click",

    event => {


      const infoButton =
        event.target.closest(
          "[data-info-item]"
        );


      if (infoButton) {

        const itemName =
          infoButton.dataset.infoItem;

        const data =
          itemDescriptions[itemName];

        if (data) {

          showInfoModal({

            ...data,

            labelAr:
              translate(itemName),

            labelEn:
              itemName

          });

        }

        return;

      }


      const routeButton =
        event.target.closest(
          "[data-route-name]"
        );


      if (routeButton) {

        openRoute(
          routeButton.dataset.routeName
        );

        return;

      }


      const cardButton =
        event.target.closest(
          "[data-card-toggle]"
        );


      if (!cardButton)
        return;


      const selectedCard =
        cardButton.closest(
          "[data-erp-card]"
        );


      if (!selectedCard)
        return;


      const shouldOpen =
        !selectedCard.classList.contains(
          "is-open"
        );


      content
        .querySelectorAll(
          "[data-erp-card]"
        )
        .forEach(card => {

          if (card !== selectedCard) {

            card.classList.remove(
              "is-open"
            );

          }

        });


      selectedCard.classList.toggle(
        "is-open",
        shouldOpen
      );

  });


  /* =========================================================
     20. INIT
  ========================================================= */

  renderStockCycle();

  renderStats();

  renderQuickActions();

  renderSections();

  renderFooter();

})();

