            },

            callback: data =>
              resolve(data?.message || 0),

            error: () =>
              resolve(0)

          });

        })
    },


    /* القيمة الدفترية */
    {
      id: "book-value",

      short: "VAL",

      labelEn: "Current Book Value",
      labelAr: "القيمة الدفترية الحالية",

      isCurrency: true,

      fetch: async () => {

