  /* =========================================================
     11. TRANSLATE
  ========================================================= */

  function translate(name) {

    if (!isArabic)
      return name;

    return (
      arabicFallback[name] ||
      (
        typeof window.__ === "function"
          ? window.__(name)
          : name
      )
    );

  }


  /* =========================================================
     12. ROUTING
  ========================================================= */

  function openRoute(name) {

    if (
      !window.frappe ||
      typeof frappe.set_route !== "function"
    )
      return;


    if (reportNames.has(name)) {

      frappe.set_route(
        "query-report",
        name
      );

      return;

    }


    if (treeDocs.has(name)) {

      frappe.set_route(
        "Tree",
        name
      );

      return;

    }


    if (singleDocs.has(name)) {

      frappe.set_route(
        "Form",
        name
      );

      return;

    }


    frappe.set_route(
      "List",
      name
    );

  }


  /* =========================================================
     13. DISPOSAL SELECTOR
  ========================================================= */

  function showDisposalSelector() {

    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-modal-close
        >
          ✕
        </button>

        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            🏢
          </span>

          <h3 class="erp-modal-title">
            ${
              isArabic
                ? "بيع أو استبعاد الأصل"
                : "Sell or Dispose Asset"
            }
          </h3>

        </div>

        <p class="erp-modal-summary">

          ${
            isArabic
              ? "اختر الإجراء المطلوب. البيع يتم من فاتورة المبيعات، أما الاستبعاد فيتم من بطاقة الأصل."
              : "Choose the required action. Selling is processed through Sales Invoice, while scrapping is performed from the Asset record."
          }

        </p>

        <div
          class="erp-quick-grid"
          style="
            margin-top:18px;
            grid-template-columns:
            repeat(2,minmax(0,1fr)) !important;
          "
        >

          <button
            type="button"
            class="erp-quick-btn"
            data-disposal-action="sell"
          >
            ${
              isArabic
                ? "بيع أصل"
                : "Sell Asset"
            }
          </button>

          <button
            type="button"
            class="erp-quick-btn"
            data-disposal-action="scrap"
          >
            ${
              isArabic
                ? "استبعاد أصل"
                : "Scrap Asset"
            }
          </button>

        </div>

      </div>

    `;


    root.appendChild(overlay);


    requestAnimationFrame(() => {

      overlay.classList.add(
        "is-visible"
      );

    });


    overlay
      .querySelector("[data-modal-close]")
      ?.addEventListener(
        "click",
        () => overlay.remove()
      );


    overlay.addEventListener(

      "click",

      event => {

        if (event.target === overlay)
          overlay.remove();

      }

    );


    overlay
      .querySelector(
        '[data-disposal-action="sell"]'
      )
      ?.addEventListener(

        "click",

        () => {

          overlay.remove();

          frappe.new_doc(
            "Sales Invoice"
          );

        }

      );


    overlay
      .querySelector(
        '[data-disposal-action="scrap"]'
      )
      ?.addEventListener(

        "click",

        () => {

          overlay.remove();

          frappe.set_route(
            "List",
            "Asset"
          );

        }

      );

  }


  /* =========================================================
     14. INFO MODAL
  ========================================================= */

  function showInfoModal(data) {

    const title =
      isArabic
        ? data.labelAr
        : data.labelEn;

    const summary =
      isArabic
        ? data.summaryAr
        : data.summaryEn;

    const steps =
      isArabic
        ? data.stepsAr
        : data.stepsEn;

    const hasSteps =
      Array.isArray(steps) &&
      steps.length > 0;

    const showText =
      isArabic
        ? "📖 عرض الخطوات"
        : "📖 Show Steps";

    const hideText =
      isArabic
        ? "📖 إخفاء الخطوات"
        : "📖 Hide Steps";


    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-modal-close
        >
          ✕
        </button>

        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            ${data.icon || "📄"}
          </span>

          <h3 class="erp-modal-title">
            ${escapeHtml(title)}
          </h3>

        </div>

        <p class="erp-modal-summary">
          ${escapeHtml(summary)}
        </p>

        ${
          hasSteps
            ? `

              <button
                type="button"
                class="erp-modal-toggle-steps"
                data-toggle-steps
              >
                ${showText}
              </button>

              <div
                class="erp-modal-steps"
                data-modal-steps
              >

                <ol class="erp-modal-steps-list">

                  ${steps
                    .map(
                      step =>
                        `<li>${escapeHtml(step)}</li>`
                    )
                    .join("")}

                </ol>

              </div>

            `
            : ""
        }

      </div>

    `;


    root.appendChild(overlay);


    requestAnimationFrame(() => {

      overlay.classList.add(
        "is-visible"
      );

    });


    overlay
      .querySelector("[data-modal-close]")
      ?.addEventListener(
        "click",
        () => overlay.remove()
      );


    overlay.addEventListener(

      "click",

      event => {

        if (event.target === overlay)
          overlay.remove();

      }

    );


    const toggleButton =
      overlay.querySelector(
        "[data-toggle-steps]"
      );

    const stepsContainer =
      overlay.querySelector(
        "[data-modal-steps]"
      );


    if (
      toggleButton &&
      stepsContainer
    ) {

      toggleButton.addEventListener(

        "click",

        () => {

          stepsContainer
            .classList
            .toggle("is-shown");


          toggleButton.textContent =
            stepsContainer
              .classList
              .contains("is-shown")

              ? hideText
              : showText;

        }

      );

    }

  }


  /* =========================================================
     15. RENDER ASSET CYCLE
  ========================================================= */

  function renderAssetCycle() {

    if (!assetCycle)
      return;


    assetCycle.innerHTML = `

      <section class="erp-cycle-container">

        <h2
          class="
            erp-section-title
            erp-cycle-title
          "
        >
          ${
            isArabic
              ? "دورة الأصول"
              : "Asset Lifecycle"
          }
        </h2>


        <div
          class="erp-cycle-grid"
          style="
            grid-template-columns:
            repeat(
              ${assetCycleCards.length},
              minmax(0,1fr)
            );
          "
        >

          ${assetCycleCards

            .map(
              (card, index) => {

                const title =
                  isArabic
                    ? card.labelAr
                    : card.labelEn;

                const description =
                  isArabic
                    ? card.descriptionAr
                    : card.descriptionEn;


                const arrow =
                  index <
                  assetCycleCards.length - 1

                    ? `
                      <span
                        class="erp-cycle-arrow"
                        aria-hidden="true"
                      >
                        ${isArabic ? "←" : "→"}
                      </span>
                    `
                    : "";


                return `

                  <div class="erp-cycle-item">

                    <button
                      type="button"
                      class="
                        erp-cycle-card
                        cycle-tone-${(index % 4) + 1}
                      "
                      data-cycle-index="${index}"
                    >

                      <span class="erp-cycle-number">
                        ${card.step}
                      </span>

                      <span class="erp-cycle-card-title">
                        ${escapeHtml(title)}
                      </span>

                      <span class="erp-cycle-description">
                        ${escapeHtml(description)}
                      </span>

                    </button>

                    ${arrow}

                  </div>

                `;

              }
            )

            .join("")}

        </div>

      </section>

    `;


    assetCycle.addEventListener(

      "click",

      event => {

        const element =
          event.target.closest(
            "[data-cycle-index]"
          );

        if (!element)
          return;


        const card =
          assetCycleCards[
            Number(
              element.dataset.cycleIndex
            )
          ];

        if (!card)
          return;


        if (
          card.action === "new"
        ) {

          frappe.new_doc(
            card.doctype
          );

          return;

        }


        if (
          card.action ===
          "disposal-selector"
        ) {

          showDisposalSelector();

          return;

        }


        openRoute(
          card.doctype
        );

      }

    );

  }


