                        '<ol class="erp-modal-steps-list">' +
                            list +
                        '</ol>' +

                    '</div>' +

                '</div>';


            root.appendChild(
                overlay
            );


            setTimeout(
                function () {

                    overlay.classList.add(
                        "is-visible"
                    );

                },
