  function escapeHtml(value) {

    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  function formatNumber(number) {

    return (
      parseFloat(number) || 0
    ).toLocaleString("en-US");
  }


  function safeCount(doctype, filters = {}) {

    return new Promise(resolve => {

      try {

        frappe.call({

          method: "frappe.client.get_count",

          args: {
            doctype,
            filters
          },

          callback: data =>
            resolve(data?.message || 0),

          error: () =>
            resolve(0)

        });

