  /* ══════════════════════════════════════════
     ٨. دوال مساعدة
  ══════════════════════════════════════════ */

  function translate(name) {

    if (!isArabic)
      return name;

    if (arabicFallback[name])
      return arabicFallback[name];

    if (typeof window.__ === "function")
      return window.__(name);

    return name;
  }


  function escapeHtml(value) {

    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  function formatNumber(num) {

    const n =
      parseFloat(num) || 0;

    return n.toLocaleString("en-US");
  }


  /* ══════════════════════════════════════════
     ٩. عرض خطوات التنفيذ
  ══════════════════════════════════════════ */

