        const card =
          zatcaCycleCards[
            Number(element.dataset.cycleIndex)
          ];

        if (!card)
          return;


        if (card.action === "new") {

          frappe.new_doc(
            card.doctype
          );

          return;
        }


        if (card.action === "form") {

          frappe.set_route(
            "Form",
            card.doctype
          );

          return;
        }


        if (card.action === "list") {

          frappe.set_route(
            "List",
            card.doctype
          );
        }

      }
    );

  }


  /* ══════════════════════════════════════════
     ١٠. إنشاء بطاقات الإحصائيات
  ══════════════════════════════════════════ */

  function renderStats() {

    if (!statsSection)
      return;


    statsSection.innerHTML = `

      <div class="erp-stats-grid">

        ${statsCards.map((card) => {

          const label =
            isArabic
              ? card.labelAr
              : card.labelEn;

          return `

            <div
              class="erp-stat-card"
              style="--stat-color:${card.color}"
            >

              <div class="erp-stat-icon">
                ${card.icon}
              </div>

              <div class="erp-stat-info">

                <span
                  class="erp-stat-value"
                  data-stat-id="${card.id}"
                >
                  ...
                </span>

                <span class="erp-stat-label">
                  ${escapeHtml(label)}
                </span>

              </div>

            </div>
          `;

        }).join("")}

      </div>
    `;


    if (window.frappe) {

      statsCards.forEach(card => {

        card.fetch().then(value => {

          const el =
            statsSection.querySelector(
              `[data-stat-id="${card.id}"]`
            );

          if (!el)
            return;

          el.textContent =
            formatNumber(value);

        });

      });

    }

  }


  /* ══════════════════════════════════════════
     ١١. مربع التفاصيل
  ══════════════════════════════════════════ */

  function showInfoModal(data) {

    const title =
      isArabic
        ? data.labelAr
        : data.labelEn;

    const summary =
      isArabic
        ? data.summaryAr
        : data.summaryEn;


    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-modal-close
        >
          ✕
        </button>

        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            ${data.icon}
          </span>

          <h3 class="erp-modal-title">
            ${escapeHtml(title)}
          </h3>

        </div>

        <p class="erp-modal-summary">
          ${escapeHtml(summary)}
        </p>

      </div>
    `;


    root.appendChild(overlay);

    requestAnimationFrame(() =>
      overlay.classList.add("is-visible")
    );


    function closeModal() {

      overlay.classList.remove(
        "is-visible"
      );

      overlay.addEventListener(
        "transitionend",
        () => overlay.remove(),
        { once: true }
      );

    }


    overlay
      .querySelector("[data-modal-close]")
      .addEventListener(
        "click",
        closeModal
      );


    overlay.addEventListener(
      "click",
      e => {

        if (e.target === overlay)
          closeModal();

      }
    );

  }


  /* ══════════════════════════════════════════
     ١٢. إنشاء البطاقات
  ══════════════════════════════════════════ */

  function renderSections() {

    content.innerHTML =
      sections.map(
        (section, sectionIndex) => {

          const sectionName =
            section[0];

          const sectionCards =
            section[1];


          const cardsHtml =
            sectionCards.map(
              (card, cardIndex) => {

                const cardName =
                  card[0];

                const icon =
                  card[1];

                const items =
                  card[2];


                const linksHtml =
                  items.map(
                    itemName => {

                      const desc =
                        itemDescriptions[itemName];

                      const detailsLabel =
                        isArabic
                          ? "تفاصيل"
                          : "Details";


                      const infoBtn =
                        desc
                          ? `
                            <button
                              type="button"
                              class="erp-info-link"
                              data-info-item="${escapeHtml(itemName)}"
                            >
                              ${detailsLabel}
                            </button>
                          `
                          : "";


                      return `

                        <div class="erp-link-row">

                          <button
                            type="button"
                            class="erp-link"
                            data-route-name="${escapeHtml(itemName)}"
                          >

                            <span class="erp-link-text">
                              ${escapeHtml(translate(itemName))}
                            </span>

                            <span class="erp-link-arrow">
                              ${isArabic ? "←" : "→"}
                            </span>

                          </button>

                          ${infoBtn}

                        </div>
                      `;

                    }
                  ).join("");


                return `

                  <article
                    class="
                      erp-card
                      tone-${(sectionIndex + cardIndex) % 5}
                    "
                    data-erp-card
                  >

                    <button
                      type="button"
                      class="erp-card-heading"
                      data-card-toggle
                      aria-expanded="false"
                    >

                      <span class="erp-icon">
                        ${icon}
                      </span>

                      <span class="erp-card-title">
                        ${escapeHtml(translate(cardName))}
                      </span>

                      <span class="erp-card-chevron">
                        ⌄
                      </span>

                    </button>


                    <div class="erp-card-links">
                      ${linksHtml}
                    </div>

                  </article>
                `;

              }
            ).join("");


          return `

            <section class="erp-module-section">

              <h2 class="erp-section-title">
                ${escapeHtml(translate(sectionName))}
              </h2>

              <div class="erp-dashboard-grid">
                ${cardsHtml}
              </div>

            </section>
          `;

        }
      ).join("");

  }


  /* ══════════════════════════════════════════
     ١٣. الفوتر
  ══════════════════════════════════════════ */

  function renderFooter() {

    if (!footerEl)
      return;


    const labels =
      footerInfo.labels;


    const phoneLabel =
      isArabic
        ? labels.phoneAr
        : labels.phoneEn;


    const emailLabel =
      isArabic
        ? labels.emailAr
        : labels.emailEn;


    const websiteLabel =
      isArabic
        ? labels.websiteAr
        : labels.websiteEn;


    footerEl.innerHTML = `

      <div class="erp-footer-inner">

        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            📞
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(phoneLabel)}:
          </span>

          <a
            href="tel:${footerInfo.phone}"
            class="erp-footer-link"
            dir="ltr"
          >
            ${escapeHtml(footerInfo.phone)}
          </a>

        </div>

        <span class="erp-footer-sep">
          |
        </span>

        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            ✉️
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(emailLabel)}:
          </span>

          <a
            href="mailto:${footerInfo.email}"
            class="erp-footer-link"
          >
            ${escapeHtml(footerInfo.email)}
          </a>

        </div>

        <span class="erp-footer-sep">
          |
        </span>

        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            🌐
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(websiteLabel)}:
          </span>

          <a
            href="https://${footerInfo.website}"
            class="erp-footer-link"
            target="_blank"
            rel="noopener"
          >
            ${escapeHtml(footerInfo.website)}
          </a>

        </div>

      </div>
    `;

  }


  /* ══════════════════════════════════════════
     ١٤. فتح الخيارات
  ══════════════════════════════════════════ */

  function openRoute(name) {

    if (
      !window.frappe ||
      typeof frappe.set_route !== "function"
    )
      return;


    if (reportNames.has(name)) {

      frappe.set_route(
        "query-report",
        name
      );

      return;
    }


    if (singleDocs.has(name)) {

      frappe.set_route(
        "Form",
        name
      );

      return;
    }


    frappe.set_route(
      "List",
      name
    );

  }


  /* ══════════════════════════════════════════
     ١٥. أحداث الضغط
  ══════════════════════════════════════════ */

  let lastToggleTime = 0;


  content.addEventListener(
    "click",
    event => {


      const infoBtn =
        event.target.closest(
          "[data-info-item]"
        );


      if (infoBtn) {

        event.preventDefault();
        event.stopPropagation();


        const itemName =
          infoBtn.dataset.infoItem;


        const desc =
          itemDescriptions[itemName];


        if (desc) {

          showInfoModal({

            icon:
              desc.icon || "📄",

            labelAr:
              translate(itemName),

            labelEn:
              itemName,

            summaryAr:
              desc.summaryAr,

            summaryEn:
              desc.summaryEn

          });

        }

        return;
      }


      const routeButton =
        event.target.closest(
          "[data-route-name]"
        );


      if (routeButton) {

        event.preventDefault();
        event.stopPropagation();


        openRoute(
          routeButton.dataset.routeName
        );

        return;
      }


      const cardButton =
        event.target.closest(
          "[data-card-toggle]"
        );


      if (!cardButton)
        return;


      const now =
        Date.now();


      if (
        now - lastToggleTime <
        400
      )
        return;


      lastToggleTime =
        now;


      const selectedCard =
        cardButton.closest(
          "[data-erp-card]"
        );


      if (!selectedCard)
        return;


      const shouldOpen =
        !selectedCard.classList.contains(
          "is-open"
        );


      content
        .querySelectorAll(
          "[data-erp-card]"
        )
        .forEach(card => {

          if (card !== selectedCard) {

            card.classList.remove(
              "is-open"
            );

            card
              .querySelector(
                "[data-card-toggle]"
              )
              ?.setAttribute(
                "aria-expanded",
                "false"
              );

          }

        });


      if (shouldOpen) {

        selectedCard.classList.add(
          "is-open"
        );

        cardButton.setAttribute(
          "aria-expanded",
          "true"
        );

      } else {

        selectedCard.classList.remove(
          "is-open"
        );

        cardButton.setAttribute(
          "aria-expanded",
          "false"
        );

      }

    }
  );


  /* ══════════════════════════════════════════
     ١٦. تشغيل
  ══════════════════════════════════════════ */

  renderZatcaCycle();
  renderStats();
  renderSections();
  renderFooter();

})();

