    0 7px 22px rgba(0, 0, 0, 0.18);
}


[data-theme="dark"]
.erp-modal-box,

html[data-theme="dark"]
.erp-modal-box {

  background:
    var(--fg-color, #20242c) !important;
}


/* =========================================================
   34. TABLET
========================================================= */

@media (max-width: 1050px) {

  .erp-dashboard-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   35. SMALL TABLET
========================================================= */

@media (max-width: 850px) {

  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   36. MOBILE
========================================================= */

@media (max-width: 650px) {

  .erp-dashboard-wrapper {
    padding:
      8px 8px 26px;
  }


  .erp-dashboard-bg {
    display: none;
  }


  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 9px;

    margin:
      12px 0 18px;
  }


  .erp-stat-card {
    padding:
      11px;

    gap: 8px;
  }


  .erp-stat-icon {
    width: 36px;
    height: 36px;

    flex-basis: 36px;

    font-size: 17px;
  }


  .erp-stat-value,
  .erp-stat-card .erp-stat-value {
    font-size:
      14px !important;
  }


  .erp-stat-label,
  .erp-stat-card .erp-stat-label {
    font-size:
      10px !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 8px;
  }


  .erp-quick-btn {
    min-height: 43px;

    padding:
      9px 7px;

    font-size:
      11.5px;
  }


  .erp-dashboard-grid {
    grid-template-columns:
      1fr !important;

    gap: 11px;
  }


  .erp-card.is-open {
    transform:
      translateY(-2px);
  }


  /* ================================
     FOOTER MOBILE
  ================================ */

  .erp-footer {

    /* حجم خط الفوتر على الجوال */
    --footer-font-size: 13px;

    margin-top: 26px;

    padding-top: 16px;
  }


  .erp-footer-inner {
    flex-direction: column;

    gap: 8px;
  }


  .erp-footer-item {
    justify-content: center;
  }


  .erp-footer-icon {
    font-size:
      15px !important;
  }


  .erp-footer-sep {
    display: none;
  }


  .erp-modal-overlay {
    align-items:
      flex-end;

    padding: 10px;
  }


  .erp-modal-box {
    max-height: 82vh;

    padding:
      22px 17px;

    border-radius:
      16px 16px 0 0;
  }

}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

