  ]);

  const reportNames = new Set([]);


  /* ─────────────────────────────────────────
     ٨. أوصاف العناصر (توضيح فقط — بدون خطوات)
  ───────────────────────────────────────── */

  const itemDescriptions = {

    /* ═══ النماذج ═══ */

    "DocType": {
      icon: "🧩",
      summaryAr: "الجدول الأساسي في Frappe — يُعرّف هيكل البيانات والحقول والصلاحيات وسير العمل لكل مستند في النظام.",
