      summaryEn: "Write JavaScript scripts that run in the browser to customize form behavior and add visual interactions."
    },

    "Scheduled Job Type": {
      icon: "⏰",
      summaryAr: "إنشاء مهام مجدولة تعمل تلقائياً في أوقات محددة (كل دقيقة، كل ساعة، يومياً) لتنفيذ عمليات دورية.",
      summaryEn: "Create scheduled jobs that run automatically at specified intervals (every minute, hourly, daily) for periodic operations."
    },

    /* ═══ الوحدات ═══ */

    "Module Def": {
      icon: "📦",
      summaryAr: "تعريف وحدات (Modules) جديدة في النظام لتنظيم المستندات والتقارير تحت أقسام محددة.",
      summaryEn: "Define new modules in the system to organize documents and reports under specific sections."
    },

    "Module Onboarding": {
      icon: "🚀",
      summaryAr: "إنشاء خطوات إعداد أولية تظهر للمستخدم عند فتح وحدة لأول مرة لتسهيل البدء.",
      summaryEn: "Create initial setup steps shown to users when opening a module for the first time for easy onboarding."
    },

    /* ═══ الحزم ═══ */

    "Package": {
      icon: "📁",
      summaryAr: "تجميع التخصيصات (DocTypes، سكريبتات، تقارير) في حزمة واحدة قابلة للتصدير والنقل بين المواقع.",
      summaryEn: "Bundle customizations (DocTypes, scripts, reports) into a single package exportable and transferable between sites."
    },

    "Package Import": {
      icon: "📥",
      summaryAr: "استيراد حزمة تخصيصات من موقع آخر وتطبيقها على الموقع الحالي.",
      summaryEn: "Import a customization package from another site and apply it to the current site."
    },

    /* ═══ سجلات النظام ═══ */

    "Background Jobs": {
      icon: "⚙️",
      summaryAr: "عرض ومراقبة المهام الخلفية الجارية والمكتملة والفاشلة في النظام (Redis Queue).",
      summaryEn: "View and monitor running, completed, and failed background jobs in the system (Redis Queue)."
    },

    "Scheduled Jobs Logs": {
      icon: "📅",
      summaryAr: "عرض سجلات تنفيذ المهام المجدولة مع حالة النجاح أو الفشل ووقت التنفيذ.",
      summaryEn: "View scheduled job execution logs with success/failure status and execution time."
    },

    "Error Logs": {
      icon: "❌",
      summaryAr: "عرض سجلات الأخطاء البرمجية (Tracebacks) التي حدثت في النظام لتتبع المشاكل وإصلاحها.",
      summaryEn: "View error tracebacks that occurred in the system for debugging and troubleshooting."
    },

    "Communication Logs": {
      icon: "📧",
      summaryAr: "عرض سجلات جميع الاتصالات (إيميلات، رسائل) المرسلة والمستقبلة عبر النظام.",
      summaryEn: "View logs of all communications (emails, messages) sent and received through the system."
    },

    "Activity Log": {
      icon: "📝",
      summaryAr: "عرض سجل نشاطات المستخدمين في النظام — تسجيل دخول، تعديل مستندات، حذف، وغيرها.",
      summaryEn: "View user activity log — logins, document edits, deletions, and other actions."
    }
  };


  /* ─────────────────────────────────────────
     ٩. دوال مساعدة
  ───────────────────────────────────────── */

  function translate(name) {
    if (!isArabic) return name;
    if (arabicFallback[name]) return arabicFallback[name];
    if (typeof window.__ === "function") return window.__(name);
    return name;
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  /* ─────────────────────────────────────────
     ١٠. مربع التفاصيل (Modal)
  ───────────────────────────────────────── */

  function showInfoModal(data) {
    const title = isArabic ? data.labelAr : data.labelEn;
    const summary = isArabic ? data.summaryAr : data.summaryEn;
    const steps = isArabic ? data.stepsAr : data.stepsEn;
    const hasSteps = Array.isArray(steps) && steps.length > 0;

    const showStepsText = isArabic ? "📖 عرض الخطوات" : "📖 Show Steps";
    const hideStepsText = isArabic ? "📖 إخفاء الخطوات" : "📖 Hide Steps";

    let stepsHtml = "";
    if (hasSteps) {
      stepsHtml = `
        <div class="erp-modal-steps" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps.map((s) => `<li>${escapeHtml(s)}</li>`).join("")}
          </ol>
        </div>`;
    }

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute("dir", isArabic ? "rtl" : "ltr");

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button type="button" class="erp-modal-close" data-modal-close aria-label="Close">✕</button>
        <div class="erp-modal-header">
          <span class="erp-modal-icon">${data.icon}</span>
          <h3 class="erp-modal-title">${escapeHtml(title)}</h3>
        </div>
        <p class="erp-modal-summary">${escapeHtml(summary)}</p>
        ${hasSteps ? `<button type="button" class="erp-modal-toggle-steps" data-toggle-steps>${showStepsText}</button>` : ""}
        ${stepsHtml}
      </div>`;

    root.appendChild(overlay);
    requestAnimationFrame(() => overlay.classList.add("is-visible"));

    function closeModal() {
      overlay.classList.remove("is-visible");
      overlay.addEventListener("transitionend", () => overlay.remove(), { once: true });
    }

    overlay.querySelector("[data-modal-close]").addEventListener("click", closeModal);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal(); });

    const toggleBtn = overlay.querySelector("[data-toggle-steps]");
    const stepsContainer = overlay.querySelector("[data-modal-steps]");
    if (toggleBtn && stepsContainer) {
      toggleBtn.addEventListener("click", () => {
        const isShowing = stepsContainer.classList.contains("is-shown");
        stepsContainer.classList.toggle("is-shown");
        toggleBtn.textContent = isShowing ? showStepsText : hideStepsText;
      });
    }
  }


  /* ─────────────────────────────────────────
     ١١. إنشاء أزرار الاختصارات
  ───────────────────────────────────────── */

  function renderQuickActions() {
    if (!quickActions) return;

    const title = isArabic ? "اختصارات سريعة" : "Quick Actions";

    quickActions.innerHTML = `
      <h2 class="erp-section-title">${escapeHtml(title)}</h2>
      <div class="erp-quick-grid">
        ${quickActionButtons.map((btn) => {
          const label = isArabic ? btn.labelAr : btn.labelEn;
          return `
            <button type="button" class="erp-quick-btn" data-new-doc="${escapeHtml(btn.doctype)}" style="--btn-color: ${btn.color}">
              <span class="erp-quick-icon" aria-hidden="true">${btn.icon}</span>
              <span class="erp-quick-label">${escapeHtml(label)}</span>
            </button>`;
        }).join("")}
      </div>`;

    quickActions.addEventListener("click", (event) => {
      const btn = event.target.closest("[data-new-doc]");
      if (!btn) return;
      const doctype = btn.dataset.newDoc;
      if (window.frappe && typeof frappe.new_doc === "function") {
        frappe.new_doc(doctype);
      }
    });
  }


  /* ─────────────────────────────────────────
     ١٢. إنشاء بطاقات المكونات
  ───────────────────────────────────────── */

  function renderSections() {
    root.setAttribute("dir", isArabic ? "rtl" : "ltr");
    root.classList.toggle("erp-dashboard-rtl", isArabic);

    content.innerHTML = sections
      .map((section, sectionIndex) => {
        const sectionName = section[0];
        const sectionCards = section[1];

        const cardsHtml = sectionCards
          .map((card, cardIndex) => {
            const cardName = card[0];
            const icon = card[1];
            const items = card[2];

            const linksHtml = items.map((itemName) => {
              const desc = itemDescriptions[itemName];
              const detailsLabel = isArabic ? "تفاصيل" : "Details";
              const infoBtn = desc
                ? `<button type="button" class="erp-info-link" data-info-item="${escapeHtml(itemName)}">${detailsLabel}</button>`
                : "";

              return `
                <div class="erp-link-row">
                  <button type="button" class="erp-link" data-route-name="${escapeHtml(itemName)}">
                    <span class="erp-link-text">${escapeHtml(translate(itemName))}</span>
                    <span class="erp-link-arrow" aria-hidden="true">${isArabic ? "←" : "→"}</span>
                  </button>
                  ${infoBtn}
                </div>`;
            }).join("");

            return `
              <article class="erp-card tone-${(sectionIndex + cardIndex) % 5}" data-erp-card>
                <button type="button" class="erp-card-heading" data-card-toggle aria-expanded="false">
                  <span class="erp-icon" aria-hidden="true">${icon}</span>
                  <span class="erp-card-title">${escapeHtml(translate(cardName))}</span>
                  <span class="erp-card-chevron" aria-hidden="true">⌄</span>
                </button>
                <div class="erp-card-links">${linksHtml}</div>
              </article>`;
          }).join("");

        return `
          <section class="erp-module-section">
            <h2 class="erp-section-title">${escapeHtml(translate(sectionName))}</h2>
            <div class="erp-dashboard-grid">${cardsHtml}</div>
          </section>`;
      }).join("");
  }


  /* ─────────────────────────────────────────
     ١٣. إنشاء الفوتر
  ───────────────────────────────────────── */

  function renderFooter() {
    if (!footerEl) return;
    const labels = footerInfo.labels;
    const phoneLabel = isArabic ? labels.phoneAr : labels.phoneEn;
    const emailLabel = isArabic ? labels.emailAr : labels.emailEn;
    const websiteLabel = isArabic ? labels.websiteAr : labels.websiteEn;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">📞</span>
          <span class="erp-footer-label">${escapeHtml(phoneLabel)}:</span>
          <a href="tel:${footerInfo.phone}" class="erp-footer-link" dir="ltr">${escapeHtml(footerInfo.phone)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉️</span>
          <span class="erp-footer-label">${escapeHtml(emailLabel)}:</span>
          <a href="mailto:${footerInfo.email}" class="erp-footer-link">${escapeHtml(footerInfo.email)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">${escapeHtml(websiteLabel)}:</span>
          <a href="https://${footerInfo.website}" class="erp-footer-link" target="_blank" rel="noopener">${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>`;
  }


  /* ─────────────────────────────────────────
     ١٤. فتح الخيار داخل ERPNext
  ───────────────────────────────────────── */

  function openRoute(name) {
    if (!window.frappe || typeof frappe.set_route !== "function") return;
    if (reportNames.has(name)) { frappe.set_route("query-report", name); return; }
    if (singleDocs.has(name)) { frappe.set_route("Form", name); return; }
    frappe.set_route("List", name);
  }


  /* ─────────────────────────────────────────
     ١٥. أحداث الضغط
  ───────────────────────────────────────── */

  let lastToggleTime = 0;

  content.addEventListener("click", (event) => {
    const infoBtn = event.target.closest("[data-info-item]");
    if (infoBtn) {
      event.preventDefault();
      event.stopPropagation();
      const itemName = infoBtn.dataset.infoItem;
      const desc = itemDescriptions[itemName];
      if (desc) {
        showInfoModal({
          icon: desc.icon || "📄",
          labelAr: translate(itemName),
          labelEn: itemName,
          summaryAr: desc.summaryAr,
          summaryEn: desc.summaryEn,
          stepsAr: desc.stepsAr,
          stepsEn: desc.stepsEn
        });
      }
      return;
    }

    const routeButton = event.target.closest("[data-route-name]");
    if (routeButton) {
      event.preventDefault();
      event.stopPropagation();
      openRoute(routeButton.dataset.routeName);
      return;
    }

    const cardButton = event.target.closest("[data-card-toggle]");
    if (!cardButton) return;

    const now = Date.now();
    if (now - lastToggleTime < 400) return;
    lastToggleTime = now;

    const selectedCard = cardButton.closest("[data-erp-card]");
    if (!selectedCard) return;

    const shouldOpen = !selectedCard.classList.contains("is-open");

    content.querySelectorAll("[data-erp-card]").forEach((card) => {
      if (card !== selectedCard) {
        card.classList.remove("is-open");
        card.querySelector("[data-card-toggle]")?.setAttribute("aria-expanded", "false");
      }
    });

    if (shouldOpen) {
      selectedCard.classList.add("is-open");
      cardButton.setAttribute("aria-expanded", "true");
    } else {
      selectedCard.classList.remove("is-open");
      cardButton.setAttribute("aria-expanded", "false");
    }
  });


  /* ─────────────────────────────────────────
     ١٦. تشغيل
  ───────────────────────────────────────── */

  renderQuickActions();
  renderSections();
  renderFooter();
})();

style:
/* =========================================================
   MUBTKIR ERP — SALES WORKSPACE
   Unified Professional Brand Theme
========================================================= */


/* =========================================================
   1. ROOT + BRAND COLORS
========================================================= */

.erp-dashboard-wrapper {
  --brand-primary: #3867AE;
  --brand-secondary: #0F84B5;
  --brand-accent: #0BA1B8;
  --brand-purple: #644DA6;

  --brand-text: #243B63;
  --brand-muted: #66758A;

  --brand-border: rgba(56, 103, 174, 0.22);
  --brand-border-strong: rgba(56, 103, 174, 0.38);

  --brand-soft: rgba(56, 103, 174, 0.07);
  --brand-soft-secondary: rgba(15, 132, 181, 0.07);
  --brand-soft-accent: rgba(11, 161, 184, 0.07);
  --brand-soft-purple: rgba(100, 77, 166, 0.07);

  position: relative;
  width: 100%;
  padding: 14px 16px 36px;
  overflow: visible;

  color: var(--brand-text);
}

.erp-dashboard-wrapper,
.erp-dashboard-wrapper * {
  box-sizing: border-box;

  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;
}


/* RTL */

.erp-dashboard-wrapper.erp-dashboard-rtl {
  direction: rtl;
  text-align: right;
}


/* =========================================================
   2. BACKGROUND LOGO
   الشعار المائي في خلفية لوحة التحكم
========================================================= */

.erp-dashboard-wrapper {
  position: relative;
  isolation: isolate;
}


/* الشعار المائي */
.erp-dashboard-bg {
  position: absolute;

  /* يبدأ أسفل بطاقات الإحصائيات تقريباً */
  top: 60px;
  left: 50%;

  width: 58%;
  max-width: 720px;
  height: auto;

  object-fit: contain;

  transform: translateX(-50%);

  /* قوة ظهور الشعار */
  opacity: 0.055;

  pointer-events: none;
  user-select: none;

  z-index: 0;
}


/* جميع محتويات الصفحة فوق الشعار */
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
  position: relative;
  z-index: 2;
}


/* ضمان شفافية منطقة المحتوى */
.erp-dashboard-content,
.erp-module-section,
.erp-dashboard-grid {
  background: transparent !important;
}


/* =========================================================
   3. CONTENT LAYER
========================================================= */

.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
  position: relative;
  z-index: 2;
}


/* =========================================================
   4. STATISTICS GRID
========================================================= */

.erp-stats-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 14px;

  margin: 18px 0 24px;
}


/* =========================================================
   5. STAT CARD
========================================================= */

.erp-stat-card {
  display: flex;

  align-items: center;

  gap: 12px;

  min-width: 0;

  padding: 16px 18px;

  border: 1px solid var(--brand-border);
  border-radius: 14px;

  background: var(--fg-color, #ffffff);

  box-shadow:
    0 4px 14px rgba(36, 59, 99, 0.06);

  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}


@media (hover: hover) {

  .erp-stat-card:hover {
    transform: translateY(-3px);

    border-color: var(--brand-border-strong);

    box-shadow:
      0 10px 26px rgba(36, 59, 99, 0.11);
  }

}


/* =========================================================
   6. STAT ICON
========================================================= */

.erp-stat-icon {
  display: flex;

  align-items: center;
  justify-content: center;

  width: 44px;
  height: 44px;

  flex: 0 0 44px;

  border-radius: 12px;

  background: var(--brand-soft);

  font-size: 21px;
}


/* =========================================================
   7. STAT INFO
   لون النص موحد لجميع بطاقات الإحصائيات
========================================================= */

.erp-stat-info {
  display: flex;

  flex-direction: column;

  gap: 3px;

  min-width: 0;

  color: var(--brand-text) !important;
}


/* الرقم / القيمة */

.erp-stat-value,
.erp-stat-card .erp-stat-value {
  color: var(--brand-text) !important;

  font-size: 18px !important;
  font-weight: 800 !important;

  line-height: 1.3;

  direction: ltr;
}


/* اسم الإحصائية */

.erp-stat-label,
.erp-stat-card .erp-stat-label {
  color: var(--brand-text) !important;

  font-size: 11.5px !important;
  font-weight: 600 !important;

  line-height: 1.45;
}


/* فرض اللون على أي عناصر داخل بطاقة الإحصائية */

.erp-stat-card .erp-stat-info,
.erp-stat-card .erp-stat-info span {
  color: var(--brand-text) !important;
}


/* =========================================================
   8. STAT CARD SOFT COLORS
   اللون يطبق على خلفية الأيقونة فقط
   وليس على النص
========================================================= */

.erp-stat-card:nth-child(1) .erp-stat-icon {
  background: var(--brand-soft);
}

.erp-stat-card:nth-child(2) .erp-stat-icon {
  background: var(--brand-soft-secondary);
}

.erp-stat-card:nth-child(3) .erp-stat-icon {
  background: var(--brand-soft-accent);
}

.erp-stat-card:nth-child(4) .erp-stat-icon {
  background: var(--brand-soft-purple);
}


/* =========================================================
   9. SECTION
========================================================= */

.erp-quick-actions {
  margin-bottom: 24px;
}

.erp-module-section {
  margin-top: 24px;
}


/* =========================================================
   10. SECTION TITLE
========================================================= */

.erp-section-title {
  position: relative;

  display: flex;

  align-items: center;

  min-height: 36px;

  margin: 0 0 14px;

  padding: 0 0 9px;

  border-bottom:
    1px solid var(--brand-border);

  color: var(--brand-text) !important;

  font-size: 18px;
  font-weight: 600;

  line-height: 1.4;
}


.erp-section-title::after {
  content: "";

  position: absolute;

  bottom: -1px;

  width: 52px;
  height: 2px;

  border-radius: 20px;

  background: var(--brand-primary);
}


.erp-dashboard-rtl
.erp-section-title::after {
  right: 0;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-section-title::after {
  left: 0;
}


/* =========================================================
   11. QUICK ACTIONS GRID
========================================================= */

.erp-quick-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 12px;
}


/* =========================================================
   12. QUICK BUTTONS
   بدون أيقونات
   لون الخط موحد
========================================================= */

.erp-quick-btn {
  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 48px;

  padding: 11px 14px;

  border:
    1px solid var(--brand-border);

  border-radius: 10px;

  outline: none;

  background: var(--brand-soft);

  color: var(--brand-primary) !important;

  font-family: inherit;

  font-size: 15px;
  font-weight: 700;

  line-height: 1.4;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}


.erp-quick-btn:nth-child(2) {
  background: var(--brand-soft-secondary);
}

.erp-quick-btn:nth-child(3) {
  background: var(--brand-soft-accent);
}

.erp-quick-btn:nth-child(4) {
  background: var(--brand-soft-purple);
}


.erp-quick-btn,
.erp-quick-btn .erp-quick-label {
  color: var(--brand-primary) !important;
}


@media (hover: hover) {

  .erp-quick-btn:hover {
    transform: translateY(-2px);

    color: var(--brand-secondary) !important;

    border-color: var(--brand-secondary);

    background:
      rgba(15, 132, 181, 0.10);

    box-shadow:
      0 6px 16px rgba(56, 103, 174, 0.12);
  }

}


.erp-quick-btn:active {
  transform: scale(0.98);
}


.erp-quick-label {
  width: 100%;

  white-space: normal;

  text-align: center;
}


/* =========================================================
   13. REPORT CARDS GRID
========================================================= */

.erp-dashboard-grid {
  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  align-items: start;

  gap: 16px;

  width: 100%;

  overflow: visible;
}


/* =========================================================
   14. REPORT CARD CLOSED
========================================================= */

.erp-card {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);

  position: relative;

  z-index: 1;

  min-width: 0;

  min-height: 74px;
  max-height: 74px;

  padding: 0 16px;

  overflow: hidden;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background: var(--fg-color, #ffffff);

  color: var(--brand-text) !important;

  box-shadow:
    0 5px 16px rgba(36, 59, 99, 0.06);

  transition:
    max-height 0.4s ease,
    transform 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease,
    padding-bottom 0.28s ease;
}


/* soft background */

.erp-card::before {
  content: "";

  position: absolute;

  inset: 0;

  z-index: 0;

  background: var(--erp-soft);

  opacity: 0;

  pointer-events: none;

  transition:
    opacity 0.25s ease;
}


/* bottom accent */

.erp-card::after {
  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  z-index: 4;

  width: 0;
  height: 3px;

  background: var(--erp-accent);

  transition:
    width 0.3s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-card::after {
  right: auto;
  left: 0;
}


/* =========================================================
   15. CARD BRAND TONES
========================================================= */

.erp-card.tone-0 {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);
}

.erp-card.tone-1 {
  --erp-accent: var(--brand-secondary);
  --erp-soft: var(--brand-soft-secondary);
}

.erp-card.tone-2 {
  --erp-accent: var(--brand-accent);
  --erp-soft: var(--brand-soft-accent);
}

.erp-card.tone-3 {
  --erp-accent: var(--brand-purple);
  --erp-soft: var(--brand-soft-purple);
}

.erp-card.tone-4 {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);
}


/* =========================================================
   16. CARD OPEN
========================================================= */

.erp-card.is-open {
  z-index: 30;

  max-height: 590px;

  padding-bottom: 15px;

  border-color:
    var(--erp-accent);

  transform:
    translateY(-5px);

  box-shadow:
    0 18px 40px rgba(36, 59, 99, 0.14);
}


.erp-card.is-open::before {
  opacity: 1;
}


.erp-card.is-open::after {
  width: 100%;
}





/* =========================================================
   17. CARD HEADING
========================================================= */

.erp-card-heading {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: center;

  gap: 8px;

  width: 100%;
  height: 72px;

  margin: 0;
  padding: 0;

  border: 0;
  border-bottom:
    1px solid transparent;

  outline: none;

  background: transparent;

  color: var(--brand-text) !important;

  font-family: inherit;

  text-align: inherit;

  cursor: pointer;

  transition:
    border-color 0.22s ease,
    margin-bottom 0.22s ease;
}


.erp-card.is-open
.erp-card-heading {
  margin-bottom: 10px;

  border-bottom-color:
    var(--brand-border);
}





/* =========================================================
   18. CARD TITLE
   لون موحد لكل البطاقات
========================================================= */

.erp-card-title,
.erp-card .erp-card-title {
  flex: 1;

  min-width: 0;

  color: var(--brand-text) !important;

  font-size: 16px;
  font-weight: 800;

  line-height: 1.5;
}


/* =========================================================
   19. CARD CHEVRON
========================================================= */

.erp-card-chevron {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  flex: 0 0 28px;

  border-radius: 8px;

  background: var(--erp-soft);

  color: var(--erp-accent) !important;

  font-size: 17px;

  transition:
    transform 0.22s ease;
}


.erp-card.is-open
.erp-card-chevron {
  transform: rotate(180deg);
}





/* =========================================================
   20. CARD LINKS
========================================================= */

.erp-card-links {
  position: relative;

  z-index: 2;

  display: grid;

  gap: 5px;

  max-height: 0;

  margin: 0;
  padding: 0;

  overflow: hidden;

  opacity: 0;

  visibility: hidden;

  pointer-events: none;

  transform:
    translateY(-8px);

  transition:
    max-height 0.38s ease,
    opacity 0.2s ease,
    visibility 0.2s ease,
    transform 0.28s ease;
}


.erp-card.is-open
.erp-card-links {
  max-height: 480px;

  overflow-y: auto;

  opacity: 1;

  visibility: visible;

  pointer-events: auto;

  transform:
    translateY(0);
}





/* =========================================================
   21. LINK ROW
========================================================= */

.erp-link-row {
  display: flex;

  align-items: center;

  gap: 6px;

  width: 100%;
}


/* =========================================================
   22. CARD LINK
   لون النص الأساسي موحد
========================================================= */

.erp-link {
  display: flex;

  align-items: center;

  gap: 7px;

  flex: 1;

  min-width: 0;

  min-height: 36px;

  padding: 7px 10px;

  border:
    1px solid transparent;

  border-radius: 8px;

  outline: none;

  background:
    transparent;

  color: var(--brand-text) !important;

  font-family: inherit;

  font-size: 13px;

  font-weight: 500;

  line-height: 1.45;

  text-align: inherit;

  cursor: pointer;

  transition:
    background 0.16s ease,
    color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;
}


.erp-link-text {
  flex: 1;

  min-width: 0;

  color: inherit !important;
}


.erp-link:hover,
.erp-link:focus {
  border-color:
    color-mix(
      in srgb,
      var(--erp-accent) 28%,
      transparent
    );

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;
}


.erp-dashboard-rtl
.erp-link:hover,

.erp-dashboard-rtl
.erp-link:focus {
  transform:
    translateX(-3px);
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:hover,

.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:focus {
  transform:
    translateX(3px);
}


/* =========================================================
   23. LINK ARROW
========================================================= */

.erp-link-arrow {
  flex: 0 0 auto;

  color:
    var(--erp-accent) !important;

  font-size: 13px;

  font-weight: 800;

  opacity: 0;

  transition:
    opacity 0.16s ease;
}


.erp-link:hover .erp-link-arrow,
.erp-link:focus .erp-link-arrow {
  opacity: 1;
}


/* =========================================================
   24. DETAILS BUTTON
========================================================= */

.erp-info-link {
  flex: 0 0 auto;

  padding: 5px 10px;

  border:
    1px solid var(--brand-border);

  border-radius: 7px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 12px;

  font-weight: 600;

  cursor: pointer;

  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}


.erp-info-link:hover {
  border-color:
    var(--brand-primary);

  background:
    rgba(56, 103, 174, 0.13);

  color:
    var(--brand-primary) !important;
}


/* =========================================================
   25. SCROLLBAR
========================================================= */

.erp-card-links::-webkit-scrollbar {
  width: 5px;
}


.erp-card-links::-webkit-scrollbar-track {
  background: transparent;
}


.erp-card-links::-webkit-scrollbar-thumb {
  border-radius: 10px;

  background:
    var(--brand-primary);
}


/* =========================================================
   26. FOOTER
   ★ حجم خط الفوتر يتم تغييره من هنا ★
========================================================= */

.erp-footer {

  /* ==========================================
     ★ غيّر هذه القيمة لتكبير/تصغير الفوتر ★
     مثال:
     14px = أصغر
     15px = الحالي
     16px = أكبر
     17px = كبير
  ========================================== */

  --footer-font-size: 15px;


  margin-top: 34px;

  padding:
    20px 12px 4px;

  border-top:
    1px solid var(--brand-border);

  color:
    var(--brand-text);
}


/* حاوية عناصر الفوتر */

.erp-footer-inner {
  display: flex;

  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap: 10px 22px;

  width: 100%;
}


/* كل عنصر في الفوتر */

.erp-footer-item {
  display: flex;

  align-items: center;

  gap: 7px;

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight: 600;

  line-height: 1.6;
}


/* أيقونة الفوتر */

.erp-footer-icon {
  font-size: 17px !important;

  line-height: 1;
}


/* اسم الحقل */

.erp-footer-label {
  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    700 !important;
}


/* رقم الهاتف / البريد / الموقع */

.erp-footer-link {
  color:
    var(--brand-primary) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600 !important;

  text-decoration: none;

  transition:
    color 0.18s ease;
}


.erp-footer-link:hover {
  color:
    var(--brand-secondary) !important;

  text-decoration:
    underline;
}


/* الفواصل */

.erp-footer-sep {
  color:
    var(--brand-border-strong) !important;

  font-size: 20px;

  font-weight: 300;

  line-height: 1;
}


/* =========================================================
   27. MODAL OVERLAY
========================================================= */

.erp-modal-overlay {
  position: fixed;

  inset: 0;

  z-index: 99999 !important;

  display: flex;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background:
    rgba(12, 27, 54, 0) !important;

  transition:
    background 0.28s ease;
}


.erp-modal-overlay.is-visible {
  background:
    rgba(12, 27, 54, 0.52) !important;
}


/* =========================================================
   28. MODAL BOX
========================================================= */

.erp-modal-box {
  position: relative;

  width: 100%;

  max-width: 480px;
  max-height: 85vh;

  padding: 28px 24px;

  overflow-y: auto;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  background:
    #ffffff !important;

  box-shadow:
    0 24px 64px rgba(12, 27, 54, 0.28) !important;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.97);

  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}


.erp-modal-overlay.is-visible
.erp-modal-box {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}


/* =========================================================
   29. MODAL CLOSE
========================================================= */

.erp-modal-close {
  position: absolute;

  top: 12px;

  display: flex;

  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: 0;

  border-radius: 8px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size: 15px;

  cursor: pointer;
}


[dir="rtl"]
.erp-modal-close {
  left: 12px;
}


[dir="ltr"]
.erp-modal-close {
  right: 12px;
}


/* =========================================================
   30. MODAL CONTENT
========================================================= */

.erp-modal-header {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-bottom: 15px;
}


.erp-modal-icon {
  font-size: 28px;

  line-height: 1;
}


.erp-modal-title {
  margin: 0;

  color:
    var(--brand-text) !important;

  font-size: 18px;

  font-weight: 800;
}


.erp-modal-summary {
  margin:
    0 0 16px;

  color:
    var(--brand-text) !important;

  font-size: 13.5px;

  line-height: 1.75;
}


/* =========================================================
   31. MODAL STEPS BUTTON
========================================================= */

.erp-modal-toggle-steps {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    8px 16px;

  border:
    1px solid var(--brand-primary);

  border-radius: 9px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 12.5px;

  font-weight: 700;

  cursor: pointer;
}


.erp-modal-toggle-steps:hover {
  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   32. MODAL STEPS
========================================================= */

.erp-modal-steps {
  max-height: 0;

  overflow: hidden;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {
  max-height: 500px;

  opacity: 1;

  margin-top: 15px;
}


.erp-modal-steps-list {
  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {
  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

  color:
    var(--brand-text) !important;

  font-size: 12.5px;

  line-height: 1.65;
}


.erp-modal-steps-list li:last-child {
  border-bottom: 0;
}


.erp-modal-steps-list li::before {
  content:
    counter(step-counter);

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  width: 22px;
  height: 22px;

  margin-inline-end: 9px;

  border-radius: 50%;

  background:
    var(--brand-primary);

  color:
    #ffffff;

  font-size: 10px;

  font-weight: 800;
}


/* =========================================================
   33. DARK MODE
========================================================= */

[data-theme="dark"]
.erp-dashboard-wrapper,

html[data-theme="dark"]
.erp-dashboard-wrapper {

  --brand-text:
    #E9EEF7;

  --brand-muted:
    #A7B2C5;

  --brand-border:
    rgba(15, 132, 181, 0.22);

  --brand-border-strong:
    rgba(15, 132, 181, 0.40);
}


[data-theme="dark"]
.erp-card,

html[data-theme="dark"]
.erp-card,

[data-theme="dark"]
.erp-stat-card,

html[data-theme="dark"]
.erp-stat-card {

  background:
    var(--fg-color, #20242c);

  box-shadow:
    0 7px 22px rgba(0, 0, 0, 0.18);
}


[data-theme="dark"]
.erp-modal-box,

html[data-theme="dark"]
.erp-modal-box {

  background:
    var(--fg-color, #20242c) !important;
}


/* =========================================================
   34. TABLET
========================================================= */

@media (max-width: 1050px) {

  .erp-dashboard-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   35. SMALL TABLET
========================================================= */

@media (max-width: 850px) {

  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   36. MOBILE
========================================================= */

@media (max-width: 650px) {

  .erp-dashboard-wrapper {
    padding:
      8px 8px 26px;
  }


  .erp-dashboard-bg {
    display: none;
  }


  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 9px;

    margin:
      12px 0 18px;
  }


  .erp-stat-card {
    padding:
      11px;

    gap: 8px;
  }


  .erp-stat-icon {
    width: 36px;
    height: 36px;

    flex-basis: 36px;

    font-size: 17px;
  }


  .erp-stat-value,
  .erp-stat-card .erp-stat-value {
    font-size:
      14px !important;
  }


  .erp-stat-label,
  .erp-stat-card .erp-stat-label {
    font-size:
      10px !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 8px;
  }


  .erp-quick-btn {
    min-height: 43px;

    padding:
      9px 7px;

    font-size:
      11.5px;
  }


  .erp-dashboard-grid {
    grid-template-columns:
      1fr !important;

    gap: 11px;
  }


  .erp-card.is-open {
    transform:
      translateY(-2px);
  }


  /* ================================
     FOOTER MOBILE
  ================================ */

  .erp-footer {

    /* حجم خط الفوتر على الجوال */
    --footer-font-size: 13px;

    margin-top: 26px;

    padding-top: 16px;
  }


  .erp-footer-inner {
    flex-direction: column;

    gap: 8px;
  }


  .erp-footer-item {
    justify-content: center;
  }


  .erp-footer-icon {
    font-size:
      15px !important;
  }


  .erp-footer-sep {
    display: none;
  }


  .erp-modal-overlay {
    align-items:
      flex-end;

    padding: 10px;
  }


  .erp-modal-box {
    max-height: 82vh;

    padding:
      22px 17px;

    border-radius:
      16px 16px 0 0;
  }

}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: none !important;
}

script:
(() => {
  /*
   * ══════════════════════════════════════════
   *  لوحة تحكم التكاملات — ERPNext Workspace
   * ══════════════════════════════════════════
   *
   *  بطاقات التكاملات + توضيح + الفوتر.
   *  بدون إحصائيات وبدون أزرار اختصار.
   */


  /* ─────────────────────────────────────────
     ١. عناصر لوحة التحكم من HTML
  ───────────────────────────────────────── */

  const root = root_element.querySelector("[data-erp-dashboard]");
  const content = root_element.querySelector("[data-dashboard-content]");
  const statsSection = root_element.querySelector("[data-stats-section]");
  const quickActions = root_element.querySelector("[data-quick-actions]");
  const footerEl = root_element.querySelector("[data-dashboard-footer]");

  if (!root || !content) return;


  /* ─────────────────────────────────────────
     ٢. معرفة لغة المستخدم الحالية
  ───────────────────────────────────────── */

  const langValue =
    window.frappe?.boot?.lang ||
    window.frappe?.boot?.user?.language ||
    document.documentElement.lang ||
    "en";

  const isArabic = String(langValue).toLowerCase().startsWith("ar");


  /* ─────────────────────────────────────────
     ٣. إعدادات الفوتر
  ───────────────────────────────────────── */

  const footerInfo = {
    phone: "0115110455",
    email: "sales@mubtkir.com",
    website: "www.mubtkir.com",
    labels: {
      phoneEn: "Phone",
      phoneAr: "الهاتف الموحد",
      emailEn: "Email",
      emailAr: "البريد الإلكتروني",
      websiteEn: "Website",
      websiteAr: "الموقع"
    }
  };


  /* ─────────────────────────────────────────
     ٤. بطاقات التكاملات
     (مطابقة للشاشة الفعلية)
  ───────────────────────────────────────── */

  const sections = [
    [
      "Integrations",
      [
        [
          "Backup",
          "💾",
          [
            "Dropbox Settings",
            "S3 Backup Settings",
            "Google Drive"
          ]
        ],

        [
          "Google Services",
          "🔗",
          [
            "Google Settings",
            "Google Contacts",
            "Google Calendar",
            "Google Drive"
          ]
        ],

        [
          "Authentication",
          "🔐",
          [
            "Social Login Key",
            "LDAP Settings",
            "OAuth Client",
            "OAuth Provider Settings"
          ]
        ],

        [
          "Settings",
          "⚙️",
          [
            "Webhook",
            "Slack Webhook URL",
            "SMS Settings"
          ]
        ],

        [
          "Push Notifications",
          "🔔",
          [
            "Push Notification Settings"
          ]
        ]
      ]
    ]
  ];


  /* ─────────────────────────────────────────
     ٥. الترجمات العربية
  ───────────────────────────────────────── */

  const arabicFallback = {
    "Integrations": "التكاملات",

    "Backup": "النسخ الاحتياطي",
    "Dropbox Settings": "إعدادات Dropbox",
    "S3 Backup Settings": "إعدادات النسخ الاحتياطي S3",
    "Google Drive": "جوجل درايف",

    "Google Services": "خدمات جوجل",
    "Google Settings": "إعدادات جوجل",
    "Google Contacts": "جهات اتصال جوجل",
    "Google Calendar": "تقويم جوجل",

    "Authentication": "المصادقة",
    "Social Login Key": "مفتاح تسجيل الدخول الاجتماعي",
    "LDAP Settings": "إعدادات LDAP",
    "OAuth Client": "عميل OAuth",
    "OAuth Provider Settings": "إعدادات مزود OAuth",

    "Settings": "الإعدادات",
    "Webhook": "ويب هوك",
    "Slack Webhook URL": "رابط ويب هوك Slack",
    "SMS Settings": "إعدادات الرسائل القصيرة",

    "Push Notifications": "الإشعارات الفورية",
    "Push Notification Settings": "إعدادات الإشعارات الفورية"
  };


  /* ─────────────────────────────────────────
     ٦. المستندات التي تفتح كنموذج إعدادات
  ───────────────────────────────────────── */

  const singleDocs = new Set([
    "Dropbox Settings",
    "S3 Backup Settings",
    "Google Settings",
    "LDAP Settings",
    "OAuth Provider Settings",
    "SMS Settings",
    "Slack Webhook URL",
    "Push Notification Settings"
  ]);

  const reportNames = new Set([]);


  /* ─────────────────────────────────────────
     ٧. أوصاف العناصر (توضيح فقط — بدون خطوات)
  ───────────────────────────────────────── */

  const itemDescriptions = {

    /* ═══ النسخ الاحتياطي ═══ */

    "Dropbox Settings": {
      icon: "📦",
      summaryAr:
        "إعداد النسخ الاحتياطي التلقائي لقاعدة البيانات والملفات إلى حساب Dropbox.",
      summaryEn:
        "Configure automatic database and file backups to a Dropbox account."
    },

    "S3 Backup Settings": {
      icon: "☁️",
      summaryAr:
        "إعداد النسخ الاحتياطي التلقائي إلى خدمة Amazon S3 أو أي خدمة متوافقة مع بروتوكول S3.",
      summaryEn:
        "Configure automatic backups to Amazon S3 or any S3-compatible storage service."
    },

    "Google Drive": {
      icon: "📁",
      summaryAr:
        "ربط النظام بحساب Google Drive لتخزين النسخ الاحتياطية أو مزامنة الملفات تلقائياً.",
      summaryEn:
        "Connect to a Google Drive account for storing backups or automatically syncing files."
    },

    /* ═══ خدمات جوجل ═══ */

    "Google Settings": {
      icon: "⚙️",
      summaryAr:
        "الإعدادات الرئيسية لربط ERPNext بخدمات Google مثل مفاتيح API ومعرفات التطبيق.",
      summaryEn:
        "Main settings for connecting ERPNext to Google services including API keys and application IDs."
    },

    "Google Contacts": {
      icon: "👤",
      summaryAr:
        "مزامنة جهات الاتصال بين ERPNext وحساب Google Contacts بشكل تلقائي ثنائي الاتجاه.",
      summaryEn:
        "Automatically sync contacts between ERPNext and Google Contacts bidirectionally."
    },

    "Google Calendar": {
      icon: "📅",
      summaryAr:
        "مزامنة الأحداث والمواعيد بين ERPNext وتقويم Google بشكل تلقائي.",
      summaryEn:
        "Automatically sync events and appointments between ERPNext and Google Calendar."
    },

    /* ═══ المصادقة ═══ */

    "Social Login Key": {
      icon: "🌐",
      summaryAr:
        "إعداد مفاتيح تسجيل الدخول عبر حسابات التواصل الاجتماعي مثل Google و Facebook و GitHub.",
      summaryEn:
        "Configure login keys for social accounts like Google, Facebook, and GitHub."
    },

    "LDAP Settings": {
      icon: "🏢",
      summaryAr:
        "ربط النظام بخادم LDAP (مثل Active Directory) للمصادقة المركزية وإدارة المستخدمين.",
      summaryEn:
        "Connect the system to an LDAP server (e.g., Active Directory) for centralized authentication and user management."
    },

    "OAuth Client": {
      icon: "🔑",
      summaryAr:
        "إنشاء وإدارة تطبيقات OAuth التي تسمح للأنظمة الخارجية بالوصول إلى بيانات ERPNext بشكل آمن.",
      summaryEn:
        "Create and manage OAuth applications that allow external systems to securely access ERPNext data."
    },

    "OAuth Provider Settings": {
      icon: "🛡️",
      summaryAr:
        "إعدادات ERPNext كمزود OAuth لتمكين الأنظمة الخارجية من المصادقة عبر حسابات ERPNext.",
      summaryEn:
        "Configure ERPNext as an OAuth provider to enable external systems to authenticate via ERPNext accounts."
    },

    /* ═══ الإعدادات ═══ */

    "Webhook": {
      icon: "🔔",
      summaryAr:
        "إنشاء إشعارات ويب هوك لإرسال بيانات تلقائياً إلى أنظمة خارجية عند حدوث أحداث معينة في ERPNext.",
      summaryEn:
        "Create webhooks to automatically send data to external systems when specific events occur in ERPNext."
    },

    "Slack Webhook URL": {
      icon: "💬",
      summaryAr:
        "ربط ERPNext بقنوات Slack لإرسال إشعارات وتنبيهات تلقائية عند حدوث أحداث معينة.",
      summaryEn:
        "Connect ERPNext to Slack channels for sending automatic notifications and alerts on specific events."
    },

    "SMS Settings": {
      icon: "📱",
      summaryAr:
        "إعداد بوابة الرسائل القصيرة (SMS Gateway) لإرسال رسائل نصية تلقائية من النظام.",
      summaryEn:
        "Configure SMS Gateway settings for sending automated text messages from the system."
    },

    /* ═══ الإشعارات الفورية ═══ */

    "Push Notification Settings": {
      icon: "📲",
      summaryAr:
        "إعداد الإشعارات الفورية (Push Notifications) لإرسال تنبيهات مباشرة إلى متصفحات وأجهزة المستخدمين.",
      summaryEn:
        "Configure push notifications to send real-time alerts to users' browsers and devices."
    }
  };


  /* ─────────────────────────────────────────
     ٨. دوال مساعدة
  ───────────────────────────────────────── */

  function translate(name) {
    if (!isArabic) return name;
    if (arabicFallback[name]) return arabicFallback[name];
    if (typeof window.__ === "function") return window.__(name);
    return name;
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  /* ─────────────────────────────────────────
     ٩. مربع التفاصيل (Modal)
  ───────────────────────────────────────── */

  function showInfoModal(data) {
    const title = isArabic ? data.labelAr : data.labelEn;
    const summary = isArabic ? data.summaryAr : data.summaryEn;
    const steps = isArabic ? data.stepsAr : data.stepsEn;
    const hasSteps = Array.isArray(steps) && steps.length > 0;

    const showStepsText = isArabic ? "📖 عرض الخطوات" : "📖 Show Steps";
    const hideStepsText = isArabic ? "📖 إخفاء الخطوات" : "📖 Hide Steps";

    let stepsHtml = "";
    if (hasSteps) {
      stepsHtml = `
        <div class="erp-modal-steps" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps.map((s) => `<li>${escapeHtml(s)}</li>`).join("")}
          </ol>
        </div>
      `;
    }

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute("dir", isArabic ? "rtl" : "ltr");

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button type="button" class="erp-modal-close" data-modal-close aria-label="Close">✕</button>
        <div class="erp-modal-header">
          <span class="erp-modal-icon">${data.icon}</span>
          <h3 class="erp-modal-title">${escapeHtml(title)}</h3>
        </div>
        <p class="erp-modal-summary">${escapeHtml(summary)}</p>
        ${hasSteps ? `<button type="button" class="erp-modal-toggle-steps" data-toggle-steps>${showStepsText}</button>` : ""}
        ${stepsHtml}
      </div>
    `;

    root.appendChild(overlay);

    requestAnimationFrame(() => {
      overlay.classList.add("is-visible");
    });

    function closeModal() {
      overlay.classList.remove("is-visible");
      overlay.addEventListener("transitionend", () => overlay.remove(), { once: true });
    }

    overlay.querySelector("[data-modal-close]").addEventListener("click", closeModal);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal(); });

    const toggleBtn = overlay.querySelector("[data-toggle-steps]");
    const stepsContainer = overlay.querySelector("[data-modal-steps]");

    if (toggleBtn && stepsContainer) {
      toggleBtn.addEventListener("click", () => {
        const isShowing = stepsContainer.classList.contains("is-shown");
        if (isShowing) {
          stepsContainer.classList.remove("is-shown");
          toggleBtn.textContent = showStepsText;
        } else {
          stepsContainer.classList.add("is-shown");
          toggleBtn.textContent = hideStepsText;
        }
      });
    }
  }


  /* ─────────────────────────────────────────
     ١٠. إنشاء بطاقات التكاملات
  ───────────────────────────────────────── */

  function renderSections() {
    root.setAttribute("dir", isArabic ? "rtl" : "ltr");
    root.classList.toggle("erp-dashboard-rtl", isArabic);

    content.innerHTML = sections
      .map((section, sectionIndex) => {
        const sectionName = section[0];
        const sectionCards = section[1];

        const cardsHtml = sectionCards
          .map((card, cardIndex) => {
            const cardName = card[0];
            const icon = card[1];
            const items = card[2];

            const linksHtml = items
              .map((itemName) => {
                const desc = itemDescriptions[itemName];
                const detailsLabel = isArabic ? "تفاصيل" : "Details";
                const infoBtn = desc
                  ? `<button type="button" class="erp-info-link" data-info-item="${escapeHtml(itemName)}">${detailsLabel}</button>`
                  : "";

                return `
                  <div class="erp-link-row">
                    <button type="button" class="erp-link" data-route-name="${escapeHtml(itemName)}">
                      <span class="erp-link-text">${escapeHtml(translate(itemName))}</span>
                      <span class="erp-link-arrow" aria-hidden="true">${isArabic ? "←" : "→"}</span>
                    </button>
                    ${infoBtn}
                  </div>
                `;
              })
              .join("");

            return `
              <article class="erp-card tone-${(sectionIndex + cardIndex) % 5}" data-erp-card>
                <button type="button" class="erp-card-heading" data-card-toggle aria-expanded="false">
                  <span class="erp-icon" aria-hidden="true">${icon}</span>
                  <span class="erp-card-title">${escapeHtml(translate(cardName))}</span>
                  <span class="erp-card-chevron" aria-hidden="true">⌄</span>
                </button>
                <div class="erp-card-links">${linksHtml}</div>
              </article>
            `;
          })
          .join("");

        return `
          <section class="erp-module-section">
            <h2 class="erp-section-title">${escapeHtml(translate(sectionName))}</h2>
            <div class="erp-dashboard-grid">${cardsHtml}</div>
          </section>
        `;
      })
      .join("");
  }


  /* ─────────────────────────────────────────
     ١١. إنشاء الفوتر
  ───────────────────────────────────────── */

  function renderFooter() {
    if (!footerEl) return;

    const labels = footerInfo.labels;
    const phoneLabel = isArabic ? labels.phoneAr : labels.phoneEn;
    const emailLabel = isArabic ? labels.emailAr : labels.emailEn;
    const websiteLabel = isArabic ? labels.websiteAr : labels.websiteEn;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">📞</span>
          <span class="erp-footer-label">${escapeHtml(phoneLabel)}:</span>
          <a href="tel:${footerInfo.phone}" class="erp-footer-link" dir="ltr">${escapeHtml(footerInfo.phone)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉️</span>
          <span class="erp-footer-label">${escapeHtml(emailLabel)}:</span>
          <a href="mailto:${footerInfo.email}" class="erp-footer-link">${escapeHtml(footerInfo.email)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">${escapeHtml(websiteLabel)}:</span>
          <a href="https://${footerInfo.website}" class="erp-footer-link" target="_blank" rel="noopener">${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>
    `;
  }


  /* ─────────────────────────────────────────
     ١٢. فتح الخيار داخل ERPNext
  ───────────────────────────────────────── */

  function openRoute(name) {
    if (!window.frappe || typeof frappe.set_route !== "function") return;

    if (reportNames.has(name)) {
      frappe.set_route("query-report", name);
      return;
    }

    if (singleDocs.has(name)) {
      frappe.set_route("Form", name);
      return;
    }

    frappe.set_route("List", name);
  }


  /* ─────────────────────────────────────────
     ١٣. أحداث الضغط
  ───────────────────────────────────────── */

  let lastToggleTime = 0;

  content.addEventListener("click", (event) => {
    /* ① زر "تفاصيل" */
    const infoBtn = event.target.closest("[data-info-item]");
    if (infoBtn) {
      event.preventDefault();
      event.stopPropagation();
      const itemName = infoBtn.dataset.infoItem;
      const desc = itemDescriptions[itemName];
      if (desc) {
        showInfoModal({
          icon: desc.icon || "📄",
          labelAr: translate(itemName),
          labelEn: itemName,
          summaryAr: desc.summaryAr,
          summaryEn: desc.summaryEn,
          stepsAr: desc.stepsAr,
          stepsEn: desc.stepsEn
        });
      }
      return;
    }

    /* ② رابط خيار */
    const routeButton = event.target.closest("[data-route-name]");
    if (routeButton) {
      event.preventDefault();
      event.stopPropagation();
      openRoute(routeButton.dataset.routeName);
      return;
    }

    /* ③ عنوان البطاقة */
    const cardButton = event.target.closest("[data-card-toggle]");
    if (!cardButton) return;

    const now = Date.now();
    if (now - lastToggleTime < 400) return;
    lastToggleTime = now;

    const selectedCard = cardButton.closest("[data-erp-card]");
    if (!selectedCard) return;

    const shouldOpen = !selectedCard.classList.contains("is-open");

    content.querySelectorAll("[data-erp-card]").forEach((card) => {
      if (card !== selectedCard) {
        card.classList.remove("is-open");
        card.querySelector("[data-card-toggle]")?.setAttribute("aria-expanded", "false");
      }
    });

    if (shouldOpen) {
      selectedCard.classList.add("is-open");
      cardButton.setAttribute("aria-expanded", "true");
    } else {
      selectedCard.classList.remove("is-open");
      cardButton.setAttribute("aria-expanded", "false");
    }
  });


  /* ─────────────────────────────────────────
     ١٤. تشغيل
  ───────────────────────────────────────── */

  renderSections();
  renderFooter();
})();

style:
/* =========================================================
   MUBTKIR ERP — SALES WORKSPACE
   Unified Professional Brand Theme
========================================================= */


/* =========================================================
   1. ROOT + BRAND COLORS
========================================================= */

.erp-dashboard-wrapper {
  --brand-primary: #3867AE;
  --brand-secondary: #0F84B5;
  --brand-accent: #0BA1B8;
  --brand-purple: #644DA6;

  --brand-text: #243B63;
  --brand-muted: #66758A;

  --brand-border: rgba(56, 103, 174, 0.22);
  --brand-border-strong: rgba(56, 103, 174, 0.38);

  --brand-soft: rgba(56, 103, 174, 0.07);
  --brand-soft-secondary: rgba(15, 132, 181, 0.07);
  --brand-soft-accent: rgba(11, 161, 184, 0.07);
  --brand-soft-purple: rgba(100, 77, 166, 0.07);

  position: relative;
  width: 100%;
  padding: 14px 16px 36px;
  overflow: visible;

  color: var(--brand-text);
}

.erp-dashboard-wrapper,
.erp-dashboard-wrapper * {
  box-sizing: border-box;

  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;
}


/* RTL */

.erp-dashboard-wrapper.erp-dashboard-rtl {
  direction: rtl;
  text-align: right;
}


/* =========================================================
   2. BACKGROUND LOGO
   الشعار المائي في خلفية لوحة التحكم
========================================================= */

.erp-dashboard-wrapper {
  position: relative;
  isolation: isolate;
}


/* الشعار المائي */
.erp-dashboard-bg {
  position: absolute;

  /* يبدأ أسفل بطاقات الإحصائيات تقريباً */
  top: 60px;
  left: 50%;

  width: 58%;
  max-width: 720px;
  height: auto;

  object-fit: contain;

  transform: translateX(-50%);

  /* قوة ظهور الشعار */
  opacity: 0.055;

  pointer-events: none;
  user-select: none;

  z-index: 0;
}


/* جميع محتويات الصفحة فوق الشعار */
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
  position: relative;
  z-index: 2;
}


/* ضمان شفافية منطقة المحتوى */
.erp-dashboard-content,
.erp-module-section,
.erp-dashboard-grid {
  background: transparent !important;
}


/* =========================================================
   3. CONTENT LAYER
========================================================= */

.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
  position: relative;
  z-index: 2;
}


/* =========================================================
   4. STATISTICS GRID
========================================================= */

.erp-stats-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 14px;

  margin: 18px 0 24px;
}


/* =========================================================
   5. STAT CARD
========================================================= */

.erp-stat-card {
  display: flex;

  align-items: center;

  gap: 12px;

  min-width: 0;

  padding: 16px 18px;

  border: 1px solid var(--brand-border);
  border-radius: 14px;

  background: var(--fg-color, #ffffff);

  box-shadow:
    0 4px 14px rgba(36, 59, 99, 0.06);

  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}


@media (hover: hover) {

  .erp-stat-card:hover {
    transform: translateY(-3px);

    border-color: var(--brand-border-strong);

    box-shadow:
      0 10px 26px rgba(36, 59, 99, 0.11);
  }

}


/* =========================================================
   6. STAT ICON
========================================================= */

.erp-stat-icon {
  display: flex;

  align-items: center;
  justify-content: center;

  width: 44px;
  height: 44px;

  flex: 0 0 44px;

  border-radius: 12px;

  background: var(--brand-soft);

  font-size: 21px;
}


/* =========================================================
   7. STAT INFO
   لون النص موحد لجميع بطاقات الإحصائيات
========================================================= */

.erp-stat-info {
  display: flex;

  flex-direction: column;

  gap: 3px;

  min-width: 0;

  color: var(--brand-text) !important;
}


/* الرقم / القيمة */

.erp-stat-value,
.erp-stat-card .erp-stat-value {
  color: var(--brand-text) !important;

  font-size: 18px !important;
  font-weight: 800 !important;

  line-height: 1.3;

  direction: ltr;
}


/* اسم الإحصائية */

.erp-stat-label,
.erp-stat-card .erp-stat-label {
  color: var(--brand-text) !important;

  font-size: 11.5px !important;
  font-weight: 600 !important;

  line-height: 1.45;
}


/* فرض اللون على أي عناصر داخل بطاقة الإحصائية */

.erp-stat-card .erp-stat-info,
.erp-stat-card .erp-stat-info span {
  color: var(--brand-text) !important;
}


/* =========================================================
   8. STAT CARD SOFT COLORS
   اللون يطبق على خلفية الأيقونة فقط
   وليس على النص
========================================================= */

.erp-stat-card:nth-child(1) .erp-stat-icon {
  background: var(--brand-soft);
}

.erp-stat-card:nth-child(2) .erp-stat-icon {
  background: var(--brand-soft-secondary);
}

.erp-stat-card:nth-child(3) .erp-stat-icon {
  background: var(--brand-soft-accent);
}

.erp-stat-card:nth-child(4) .erp-stat-icon {
  background: var(--brand-soft-purple);
}


/* =========================================================
   9. SECTION
========================================================= */

.erp-quick-actions {
  margin-bottom: 24px;
}

.erp-module-section {
  margin-top: 24px;
}


/* =========================================================
   10. SECTION TITLE
========================================================= */

.erp-section-title {
  position: relative;

  display: flex;

  align-items: center;

  min-height: 36px;

  margin: 0 0 14px;

  padding: 0 0 9px;

  border-bottom:
    1px solid var(--brand-border);

  color: var(--brand-text) !important;

  font-size: 18px;
  font-weight: 600;

  line-height: 1.4;
}


.erp-section-title::after {
  content: "";

  position: absolute;

  bottom: -1px;

  width: 52px;
  height: 2px;

  border-radius: 20px;

  background: var(--brand-primary);
}


.erp-dashboard-rtl
.erp-section-title::after {
  right: 0;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-section-title::after {
  left: 0;
}


/* =========================================================
   11. QUICK ACTIONS GRID
========================================================= */

.erp-quick-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 12px;
}


/* =========================================================
   12. QUICK BUTTONS
   بدون أيقونات
   لون الخط موحد
========================================================= */

.erp-quick-btn {
  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 48px;

  padding: 11px 14px;

  border:
    1px solid var(--brand-border);

  border-radius: 10px;

  outline: none;

  background: var(--brand-soft);

  color: var(--brand-primary) !important;

  font-family: inherit;

  font-size: 15px;
  font-weight: 700;

  line-height: 1.4;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}


.erp-quick-btn:nth-child(2) {
  background: var(--brand-soft-secondary);
}

.erp-quick-btn:nth-child(3) {
  background: var(--brand-soft-accent);
}

.erp-quick-btn:nth-child(4) {
  background: var(--brand-soft-purple);
}


.erp-quick-btn,
.erp-quick-btn .erp-quick-label {
  color: var(--brand-primary) !important;
}


@media (hover: hover) {

  .erp-quick-btn:hover {
    transform: translateY(-2px);

    color: var(--brand-secondary) !important;

    border-color: var(--brand-secondary);

    background:
      rgba(15, 132, 181, 0.10);

    box-shadow:
      0 6px 16px rgba(56, 103, 174, 0.12);
  }

}


.erp-quick-btn:active {
  transform: scale(0.98);
}


.erp-quick-label {
  width: 100%;

  white-space: normal;

  text-align: center;
}


/* =========================================================
   13. REPORT CARDS GRID
========================================================= */

.erp-dashboard-grid {
  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  align-items: start;

  gap: 16px;

  width: 100%;

  overflow: visible;
}


/* =========================================================
   14. REPORT CARD CLOSED
========================================================= */

.erp-card {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);

  position: relative;

  z-index: 1;

  min-width: 0;

  min-height: 74px;
  max-height: 74px;

  padding: 0 16px;

  overflow: hidden;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background: var(--fg-color, #ffffff);

  color: var(--brand-text) !important;

  box-shadow:
    0 5px 16px rgba(36, 59, 99, 0.06);

  transition:
    max-height 0.4s ease,
    transform 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease,
    padding-bottom 0.28s ease;
}


/* soft background */

.erp-card::before {
  content: "";

  position: absolute;

  inset: 0;

  z-index: 0;

  background: var(--erp-soft);

  opacity: 0;

  pointer-events: none;

  transition:
    opacity 0.25s ease;
}


/* bottom accent */

.erp-card::after {
  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  z-index: 4;

  width: 0;
  height: 3px;

  background: var(--erp-accent);

  transition:
    width 0.3s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-card::after {
  right: auto;
  left: 0;
}


/* =========================================================
   15. CARD BRAND TONES
========================================================= */

.erp-card.tone-0 {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);
}

.erp-card.tone-1 {
  --erp-accent: var(--brand-secondary);
  --erp-soft: var(--brand-soft-secondary);
}

.erp-card.tone-2 {
  --erp-accent: var(--brand-accent);
  --erp-soft: var(--brand-soft-accent);
}

.erp-card.tone-3 {
  --erp-accent: var(--brand-purple);
  --erp-soft: var(--brand-soft-purple);
}

.erp-card.tone-4 {
  --erp-accent: var(--brand-primary);
  --erp-soft: var(--brand-soft);
}


/* =========================================================
   16. CARD OPEN
========================================================= */

.erp-card.is-open {
  z-index: 30;

  max-height: 590px;

  padding-bottom: 15px;

  border-color:
    var(--erp-accent);

  transform:
    translateY(-5px);

  box-shadow:
    0 18px 40px rgba(36, 59, 99, 0.14);
}


.erp-card.is-open::before {
  opacity: 1;
}


.erp-card.is-open::after {
  width: 100%;
}





/* =========================================================
   17. CARD HEADING
========================================================= */

.erp-card-heading {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: center;

  gap: 8px;

  width: 100%;
  height: 72px;

  margin: 0;
  padding: 0;

  border: 0;
  border-bottom:
    1px solid transparent;

  outline: none;

  background: transparent;

  color: var(--brand-text) !important;

  font-family: inherit;

  text-align: inherit;

  cursor: pointer;

  transition:
    border-color 0.22s ease,
    margin-bottom 0.22s ease;
}


.erp-card.is-open
.erp-card-heading {
  margin-bottom: 10px;

  border-bottom-color:
    var(--brand-border);
}





/* =========================================================
   18. CARD TITLE
   لون موحد لكل البطاقات
========================================================= */

.erp-card-title,
.erp-card .erp-card-title {
  flex: 1;

  min-width: 0;

  color: var(--brand-text) !important;

  font-size: 16px;
  font-weight: 800;

  line-height: 1.5;
}


/* =========================================================
   19. CARD CHEVRON
========================================================= */

.erp-card-chevron {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  flex: 0 0 28px;

  border-radius: 8px;

  background: var(--erp-soft);

  color: var(--erp-accent) !important;

  font-size: 17px;

  transition:
    transform 0.22s ease;
}


.erp-card.is-open
.erp-card-chevron {
  transform: rotate(180deg);
}





/* =========================================================
   20. CARD LINKS
========================================================= */

.erp-card-links {
  position: relative;

  z-index: 2;

  display: grid;

  gap: 5px;

  max-height: 0;

  margin: 0;
  padding: 0;

  overflow: hidden;

  opacity: 0;

  visibility: hidden;

  pointer-events: none;

  transform:
    translateY(-8px);

  transition:
    max-height 0.38s ease,
    opacity 0.2s ease,
    visibility 0.2s ease,
    transform 0.28s ease;
}


.erp-card.is-open
.erp-card-links {
  max-height: 480px;

  overflow-y: auto;

  opacity: 1;

  visibility: visible;

  pointer-events: auto;

  transform:
    translateY(0);
}





/* =========================================================
   21. LINK ROW
========================================================= */

.erp-link-row {
  display: flex;

  align-items: center;

  gap: 6px;

  width: 100%;
}


/* =========================================================
   22. CARD LINK
   لون النص الأساسي موحد
========================================================= */

.erp-link {
  display: flex;

  align-items: center;

  gap: 7px;

  flex: 1;

  min-width: 0;

  min-height: 36px;

  padding: 7px 10px;

  border:
    1px solid transparent;

  border-radius: 8px;

  outline: none;

  background:
    transparent;

  color: var(--brand-text) !important;

  font-family: inherit;

  font-size: 13px;

  font-weight: 500;

  line-height: 1.45;

  text-align: inherit;

  cursor: pointer;

  transition:
    background 0.16s ease,
    color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;
}


.erp-link-text {
  flex: 1;

  min-width: 0;

  color: inherit !important;
}


.erp-link:hover,
.erp-link:focus {
  border-color:
    color-mix(
      in srgb,
      var(--erp-accent) 28%,
      transparent
    );

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;
}


.erp-dashboard-rtl
.erp-link:hover,

.erp-dashboard-rtl
.erp-link:focus {
  transform:
    translateX(-3px);
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:hover,

.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:focus {
  transform:
    translateX(3px);
}


/* =========================================================
   23. LINK ARROW
========================================================= */

.erp-link-arrow {
  flex: 0 0 auto;

  color:
    var(--erp-accent) !important;

  font-size: 13px;

  font-weight: 800;

  opacity: 0;

  transition:
    opacity 0.16s ease;
}


.erp-link:hover .erp-link-arrow,
.erp-link:focus .erp-link-arrow {
  opacity: 1;
}


/* =========================================================
   24. DETAILS BUTTON
========================================================= */

.erp-info-link {
  flex: 0 0 auto;

  padding: 5px 10px;

  border:
    1px solid var(--brand-border);

  border-radius: 7px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 12px;

  font-weight: 600;

  cursor: pointer;

  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}


.erp-info-link:hover {
  border-color:
    var(--brand-primary);

  background:
    rgba(56, 103, 174, 0.13);

  color:
    var(--brand-primary) !important;
}


/* =========================================================
   25. SCROLLBAR
========================================================= */

.erp-card-links::-webkit-scrollbar {
  width: 5px;
}


.erp-card-links::-webkit-scrollbar-track {
  background: transparent;
}


.erp-card-links::-webkit-scrollbar-thumb {
  border-radius: 10px;

  background:
    var(--brand-primary);
}


/* =========================================================
   26. FOOTER
   ★ حجم خط الفوتر يتم تغييره من هنا ★
========================================================= */

.erp-footer {

  /* ==========================================
     ★ غيّر هذه القيمة لتكبير/تصغير الفوتر ★
     مثال:
     14px = أصغر
     15px = الحالي
     16px = أكبر
     17px = كبير
  ========================================== */

  --footer-font-size: 15px;


  margin-top: 34px;

  padding:
    20px 12px 4px;

  border-top:
    1px solid var(--brand-border);

  color:
    var(--brand-text);
}


/* حاوية عناصر الفوتر */

.erp-footer-inner {
  display: flex;

  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap: 10px 22px;

  width: 100%;
}


/* كل عنصر في الفوتر */

.erp-footer-item {
  display: flex;

  align-items: center;

  gap: 7px;

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight: 600;

  line-height: 1.6;
}


/* أيقونة الفوتر */

.erp-footer-icon {
  font-size: 17px !important;

  line-height: 1;
}


/* اسم الحقل */

.erp-footer-label {
  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    700 !important;
}


/* رقم الهاتف / البريد / الموقع */

.erp-footer-link {
  color:
    var(--brand-primary) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600 !important;

  text-decoration: none;

  transition:
    color 0.18s ease;
}


.erp-footer-link:hover {
  color:
    var(--brand-secondary) !important;

  text-decoration:
    underline;
}


/* الفواصل */

.erp-footer-sep {
  color:
    var(--brand-border-strong) !important;

  font-size: 20px;

  font-weight: 300;

  line-height: 1;
}


/* =========================================================
   27. MODAL OVERLAY
========================================================= */

.erp-modal-overlay {
  position: fixed;

  inset: 0;

  z-index: 99999 !important;

  display: flex;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background:
    rgba(12, 27, 54, 0) !important;

  transition:
    background 0.28s ease;
}


.erp-modal-overlay.is-visible {
  background:
    rgba(12, 27, 54, 0.52) !important;
}


/* =========================================================
   28. MODAL BOX
========================================================= */

.erp-modal-box {
  position: relative;

  width: 100%;

  max-width: 480px;
  max-height: 85vh;

  padding: 28px 24px;

  overflow-y: auto;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  background:
    #ffffff !important;

  box-shadow:
    0 24px 64px rgba(12, 27, 54, 0.28) !important;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.97);

  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}


.erp-modal-overlay.is-visible
.erp-modal-box {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}


/* =========================================================
   29. MODAL CLOSE
========================================================= */

.erp-modal-close {
  position: absolute;

  top: 12px;

  display: flex;

  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: 0;

  border-radius: 8px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size: 15px;

  cursor: pointer;
}


[dir="rtl"]
.erp-modal-close {
  left: 12px;
}


[dir="ltr"]
.erp-modal-close {
  right: 12px;
}


/* =========================================================
   30. MODAL CONTENT
========================================================= */

.erp-modal-header {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-bottom: 15px;
}


.erp-modal-icon {
  font-size: 28px;

  line-height: 1;
}


.erp-modal-title {
  margin: 0;

  color:
    var(--brand-text) !important;

  font-size: 18px;

  font-weight: 800;
}


.erp-modal-summary {
  margin:
    0 0 16px;

  color:
    var(--brand-text) !important;

  font-size: 13.5px;

  line-height: 1.75;
}


/* =========================================================
   31. MODAL STEPS BUTTON
========================================================= */

.erp-modal-toggle-steps {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    8px 16px;

  border:
    1px solid var(--brand-primary);

  border-radius: 9px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 12.5px;

  font-weight: 700;

  cursor: pointer;
}


.erp-modal-toggle-steps:hover {
  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   32. MODAL STEPS
========================================================= */

.erp-modal-steps {
  max-height: 0;

  overflow: hidden;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {
  max-height: 500px;

  opacity: 1;

  margin-top: 15px;
}


.erp-modal-steps-list {
  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {
  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

  color:
    var(--brand-text) !important;

  font-size: 12.5px;

  line-height: 1.65;
}


.erp-modal-steps-list li:last-child {
  border-bottom: 0;
}


.erp-modal-steps-list li::before {
  content:
    counter(step-counter);

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  width: 22px;
  height: 22px;

  margin-inline-end: 9px;

  border-radius: 50%;

  background:
    var(--brand-primary);

  color:
    #ffffff;

  font-size: 10px;

  font-weight: 800;
}


/* =========================================================
   33. DARK MODE
========================================================= */

[data-theme="dark"]
.erp-dashboard-wrapper,

html[data-theme="dark"]
.erp-dashboard-wrapper {

  --brand-text:
    #E9EEF7;

  --brand-muted:
    #A7B2C5;

  --brand-border:
    rgba(15, 132, 181, 0.22);

  --brand-border-strong:
    rgba(15, 132, 181, 0.40);
}


[data-theme="dark"]
.erp-card,

html[data-theme="dark"]
.erp-card,

[data-theme="dark"]
.erp-stat-card,

html[data-theme="dark"]
.erp-stat-card {

  background:
    var(--fg-color, #20242c);

  box-shadow:
    0 7px 22px rgba(0, 0, 0, 0.18);
}


[data-theme="dark"]
.erp-modal-box,

html[data-theme="dark"]
.erp-modal-box {

  background:
    var(--fg-color, #20242c) !important;
}


/* =========================================================
   34. TABLET
========================================================= */

@media (max-width: 1050px) {

  .erp-dashboard-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   35. SMALL TABLET
========================================================= */

@media (max-width: 850px) {

  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

}


/* =========================================================
   36. MOBILE
========================================================= */

@media (max-width: 650px) {

  .erp-dashboard-wrapper {
    padding:
      8px 8px 26px;
  }


  .erp-dashboard-bg {
    display: none;
  }


  .erp-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 9px;

    margin:
      12px 0 18px;
  }


  .erp-stat-card {
    padding:
      11px;

    gap: 8px;
  }


  .erp-stat-icon {
    width: 36px;
    height: 36px;

    flex-basis: 36px;

    font-size: 17px;
  }


  .erp-stat-value,
  .erp-stat-card .erp-stat-value {
    font-size:
      14px !important;
  }


  .erp-stat-label,
  .erp-stat-card .erp-stat-label {
    font-size:
      10px !important;
  }


  .erp-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap: 8px;
  }


  .erp-quick-btn {
    min-height: 43px;

    padding:
      9px 7px;

    font-size:
      11.5px;
  }


  .erp-dashboard-grid {
    grid-template-columns:
      1fr !important;

    gap: 11px;
  }


  .erp-card.is-open {
    transform:
      translateY(-2px);
  }


  /* ================================
     FOOTER MOBILE
  ================================ */

  .erp-footer {

    /* حجم خط الفوتر على الجوال */
    --footer-font-size: 13px;

    margin-top: 26px;

    padding-top: 16px;
  }


  .erp-footer-inner {
    flex-direction: column;

    gap: 8px;
  }


  .erp-footer-item {
    justify-content: center;
  }


  .erp-footer-icon {
    font-size:
      15px !important;
  }


  .erp-footer-sep {
    display: none;
  }


  .erp-modal-overlay {
    align-items:
      flex-end;

    padding: 10px;
  }


  .erp-modal-box {
    max-height: 82vh;

    padding:
      22px 17px;

    border-radius:
      16px 16px 0 0;
  }

}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: none !important;
}

