  ========================================================= */

  function translate(name) {

    if (!isArabic)
      return name;

    return (
      arabicFallback[name] ||
      name
    );
  }


  /* =========================================================
     10. ROUTING
  ========================================================= */

  function openRoute(name) {

    try {

      if (reportNames.has(name)) {

        frappe.set_route(
          "query-report",
          name
        );

        return;
      }


      if (treeDocs.has(name)) {

        frappe.set_route(
          "Tree",
          name
        );

        return;
      }


      frappe.set_route(
        "List",
        name
      );

    } catch (e) {

      console.error(
        "HR Route Error:",
        name,
        e
      );

    }
  }


  function newDoc(doctype) {

    try {

      frappe.new_doc(
        doctype
      );

    } catch (e) {

      console.error(
        "HR New Doc Error:",
        doctype,
        e
      );

    }
  }


  /* =========================================================
     11. GENERIC SELECTOR
  ========================================================= */

  function showSelector(titleAr, titleEn, items) {

    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-selector-close
        >
          ✕
        </button>

        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            👤
          </span>

          <h3 class="erp-modal-title">
            ${
              isArabic
                ? titleAr
                : titleEn
            }
          </h3>

        </div>


        <div
          class="erp-quick-grid"
          style="
            margin-top:18px;
            grid-template-columns:
            repeat(${items.length}, minmax(0,1fr)) !important;
          "
        >

          ${items
            .map(
              (item, index) => `

                <button
                  type="button"
                  class="erp-quick-btn"
                  data-selector-index="${index}"
                >

                  ${
                    escapeHtml(
                      isArabic
                        ? item.labelAr
                        : item.labelEn
                    )
                  }

                </button>

              `
            )
            .join("")}

        </div>

      </div>

    `;


    root.appendChild(overlay);


    requestAnimationFrame(() => {

      overlay.classList.add(
        "is-visible"
      );

    });


    overlay
      .querySelector("[data-selector-close]")
      ?.addEventListener(
        "click",
        () => overlay.remove()
      );


    overlay.addEventListener(
      "click",
      event => {

        if (event.target === overlay)
          overlay.remove();

      }
    );


    overlay
      .querySelectorAll(
        "[data-selector-index]"
      )
      .forEach(button => {

        button.addEventListener(
          "click",
          () => {

            const item =
              items[
                Number(
                  button.dataset.selectorIndex
                )
              ];


            overlay.remove();


            if (!item)
              return;


            if (item.action === "new") {

              newDoc(
                item.doctype
              );

              return;
            }


            openRoute(
              item.doctype
            );

          }
        );

      });

  }


