  /* =========================================================
     15. RENDER SECTIONS
  ========================================================= */

  function renderSections() {

    if (!content)
      return;


    content.innerHTML =
      sections
        .map(
          (section, sectionIndex) => {

            const cards =
              section[1]
                .map(
                  (card, cardIndex) => {

                    const links =
                      card[2]
                        .map(
                          item => `

                            <div class="erp-link-row">

                              <button
                                type="button"
                                class="erp-link"
                                data-hr-route="${escapeHtml(item)}"
                              >

                                <span class="erp-link-text">
                                  ${escapeHtml(translate(item))}
                                </span>

                                <span class="erp-link-arrow">
                                  ${isArabic ? "←" : "→"}
                                </span>

                              </button>

                            </div>

                          `
                        )
                        .join("");


                    return `

                      <article
                        class="
                          erp-card
                          tone-${(sectionIndex + cardIndex) % 5}
                        "
                        data-hr-card
                      >

                        <button
                          type="button"
                          class="erp-card-heading"
                          data-hr-toggle
                          aria-expanded="false"
                        >

                          <span class="erp-icon">
                            ${card[1]}
                          </span>

                          <span class="erp-card-title">
                            ${escapeHtml(translate(card[0]))}
                          </span>

                          <span class="erp-card-chevron">
                            ⌄
                          </span>

                        </button>


                        <div class="erp-card-links">
                          ${links}
                        </div>

                      </article>

                    `;

                  }
                )
                .join("");


            return `

              <section class="erp-module-section">

                <h2 class="erp-section-title">
                  ${escapeHtml(translate(section[0]))}
                </h2>

                <div class="erp-dashboard-grid">
                  ${cards}
                </div>

              </section>

            `;

          }
        )
        .join("");


    content.addEventListener(
      "click",
      event => {


        const routeButton =
          event.target.closest(
            "[data-hr-route]"
          );


        if (routeButton) {

          event.preventDefault();

          openRoute(
            routeButton.dataset.hrRoute
          );

          return;
        }


        const toggle =
          event.target.closest(
            "[data-hr-toggle]"
          );


        if (!toggle)
          return;


        const selectedCard =
          toggle.closest(
            "[data-hr-card]"
          );


        if (!selectedCard)
          return;


        const shouldOpen =
          !selectedCard
            .classList
            .contains(
              "is-open"
            );


        content
          .querySelectorAll(
            "[data-hr-card]"
          )
          .forEach(card => {

            if (
              card !== selectedCard
            ) {

              card.classList.remove(
                "is-open"
              );

            }

          });


        selectedCard
          .classList
          .toggle(
            "is-open",
            shouldOpen
          );

      }
    );

  }


