/* =========================================================
   MUBTKIR ERP — BUYING WORKSPACE
   Unified Professional Brand Theme
   لوحة تحكم قسم المشتريات
========================================================= */


/* =========================================================
   1. ROOT + BRAND COLORS
   ألوان الهوية الرسمية
========================================================= */

.erp-dashboard-wrapper {

  --brand-primary: #3867AE;
  --brand-secondary: #0F84B5;
  --brand-accent: #0BA1B8;
  --brand-purple: #644DA6;

  --brand-text: #243B63;
  --brand-muted: #66758A;

  --brand-border: rgba(56, 103, 174, 0.22);
  --brand-border-strong: rgba(56, 103, 174, 0.38);

  --brand-soft: rgba(56, 103, 174, 0.07);
  --brand-soft-secondary: rgba(15, 132, 181, 0.07);
  --brand-soft-accent: rgba(11, 161, 184, 0.07);
  --brand-soft-purple: rgba(100, 77, 166, 0.07);

  position: relative;
  isolation: isolate;

  width: 100%;

  padding: 14px 16px 36px;

  overflow: visible;

  color: var(--brand-text);
}


/* =========================================================
   2. FONT
========================================================= */

.erp-dashboard-wrapper,
.erp-dashboard-wrapper * {

  box-sizing: border-box;

  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;
}


/* =========================================================
   3. RTL
========================================================= */

.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;
  text-align: right;
}


/* =========================================================
   BACKGROUND
   صورة واحدة في الخلفية بدون تكرار
========================================================= */

.erp-dashboard-bg {
    position: absolute !important;

    top: 50px;
    left: 50%;

    /* حجم الصورة */
    width: 78%;
    max-width: 1200px;

    height: auto;

    transform: translateX(-50%);

    /* الشفافية */
    opacity: 0.03;

    object-fit: contain;

    pointer-events: none;
    user-select: none;

    z-index: 0;
}


/* الحاوية الرئيسية */
.erp-dashboard-wrapper {
    position: relative !important;
    isolation: isolate;
}


/* المحتوى فوق الخلفية */
.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
    position: relative !important;
    z-index: 2;
}

/* =========================================================
   المحتوى فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {

    position: relative;

    z-index: 2;
}
/* =========================================================
   إبقاء جميع عناصر الداشبورد فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
    position: relative;
    z-index: 2;
}

/* =========================================================
   5. CONTENT LAYER
   جميع المحتويات تظهر فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {

  position: relative;

  z-index: 2;
}


.erp-dashboard-content,
.erp-module-section,
.erp-dashboard-grid {

  background: transparent !important;
}


/* =========================================================
   6. SECTION TITLE
========================================================= */

.erp-section-title {

  position: relative;

  display: flex;
  align-items: center;

  min-height: 36px;

  margin: 0 0 16px;

  padding: 0 0 10px;

  border-bottom:
    1px solid var(--brand-border);

  color:
    var(--brand-text) !important;

  font-size: 18px;
  font-weight: 700;

  line-height: 1.4;
}


.erp-section-title::after {

  content: "";

  position: absolute;

  bottom: -1px;

  width: 52px;
  height: 2px;

  border-radius: 20px;

  background: var(--brand-primary);
}


.erp-dashboard-rtl
.erp-section-title::after {

  right: 0;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-section-title::after {

  left: 0;
}


/* =========================================================
   7. PURCHASE CYCLE SECTION
========================================================= */

.erp-purchase-cycle-section {

  margin: 18px 0 24px;
}


.erp-cycle-container {

  position: relative;

  padding: 18px 18px 20px;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  /*
     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة
  */

  background:
    rgba(255, 255, 255, 0.94);

  box-shadow:
    0 5px 18px rgba(36, 59, 99, 0.06);
}


.erp-cycle-title {

  margin-bottom: 20px;
}


/* =========================================================
   SALES / PURCHASE CYCLE GRID
   توزيع البطاقات على كامل عرض الصفحة
========================================================= */

.erp-cycle-grid {
  display: grid;

  grid-template-columns:
    repeat(5, minmax(0, 1fr));

  gap: 18px;

  width: 100%;

  align-items: stretch;
}


.erp-cycle-item {
  position: relative;

  display: flex;

  width: 100%;

  min-width: 0;
}


/* البطاقة تتمدد حسب عرض العمود */
.erp-cycle-card {
  width: 100%;

  min-width: 0;

  min-height: 180px;
}

/* =========================================================
   9. PURCHASE CYCLE CARD
========================================================= */

.erp-cycle-card {

  --cycle-color:
    var(--brand-primary);

  --cycle-soft:
    var(--brand-soft);

  position: relative;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: flex-start;

  width: 100%;

  min-width: 0;
  min-height: 180px;

  padding: 17px 11px 15px;

  overflow: hidden;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  outline: none;

  background:
    rgba(255, 255, 255, 0.96);

  color:
    var(--brand-text) !important;

  font-family: inherit;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.20s ease,
    border-color 0.20s ease,
    box-shadow 0.20s ease;
}


.erp-cycle-card::before {

  content: "";

  position: absolute;

  inset: 0;

  border-radius: inherit;

  background:
    var(--cycle-soft);

  opacity: 0.42;

  pointer-events: none;
}


.erp-cycle-card::after {

  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  width: 0;
  height: 3px;

  background:
    var(--cycle-color);

  transition:
    width 0.25s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-cycle-card::after {

  right: auto;
  left: 0;
}


.erp-cycle-card > * {

  position: relative;

  z-index: 2;
}


@media (hover: hover) {

  .erp-cycle-card:hover {

    transform:
      translateY(-4px);

    border-color:
      var(--cycle-color);

    box-shadow:
      0 12px 28px rgba(36, 59, 99, 0.12);
  }


  .erp-cycle-card:hover::after {

    width: 100%;
  }
}


/* =========================================================
   10. CYCLE NUMBER
========================================================= */

.erp-cycle-number {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  margin-bottom: 14px;

  border-radius: 50%;

  background:
    var(--cycle-color);

  color:
    #ffffff !important;

  font-size: 18px;
  font-weight: 800;

  line-height: 1;

  box-shadow:
    0 5px 14px rgba(36, 59, 99, 0.12);
}


/* =========================================================
   11. CYCLE TITLE
========================================================= */

.erp-cycle-card-title {

  display: block;

  width: 100%;

  margin-bottom: 7px;

  color:
    var(--brand-text) !important;

  font-size: 13.5px;
  font-weight: 800;

  line-height: 1.45;
}


/* =========================================================
   12. CYCLE DESCRIPTION
========================================================= */

.erp-cycle-description {

  display: block;

  width: 100%;

  color:
    var(--brand-muted) !important;

  font-size: 10.5px;
  font-weight: 500;

  line-height: 1.65;
}


/* =========================================================
   13. CYCLE BRAND COLORS
========================================================= */

.erp-cycle-card.cycle-tone-1 {

  --cycle-color:
    var(--brand-primary);

  --cycle-soft:
    var(--brand-soft);
}


.erp-cycle-card.cycle-tone-2 {

  --cycle-color:
    var(--brand-secondary);

  --cycle-soft:
    var(--brand-soft-secondary);
}


.erp-cycle-card.cycle-tone-3 {

  --cycle-color:
    var(--brand-accent);

  --cycle-soft:
    var(--brand-soft-accent);
}


.erp-cycle-card.cycle-tone-4 {

  --cycle-color:
    var(--brand-purple);

  --cycle-soft:
    var(--brand-soft-purple);
}


/* =========================================================
   14. CYCLE ARROW
========================================================= */

.erp-cycle-arrow {

  position: absolute;

  top: 50%;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 20px;
  height: 20px;

  color:
    var(--brand-primary) !important;

  font-size: 20px;
  font-weight: 800;

  line-height: 1;

  opacity: 0.55;

  transform:
    translateY(-50%);

  pointer-events: none;

  z-index: 10;
}


.erp-dashboard-rtl
.erp-cycle-arrow {

  left: -17px;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-cycle-arrow {

  right: -17px;
}


/* =========================================================
   15. OVERVIEW SECTION
========================================================= */

.erp-stats-section {

  margin: 0 0 24px;
}


.erp-overview-container {

  padding: 18px;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  background:
    rgba(255, 255, 255, 0.94);

  box-shadow:
    0 5px 18px rgba(36, 59, 99, 0.06);
}


/* =========================================================
   16. STATS GRID
========================================================= */

.erp-stats-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 14px;

  margin: 0;
}


/* =========================================================
   17. STAT CARD
========================================================= */

.erp-stat-card {

  display: flex;

  align-items: center;

  gap: 13px;

  min-width: 0;

  min-height: 88px;

  padding: 16px 18px;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.96);

  box-shadow:
    0 4px 14px rgba(36, 59, 99, 0.05);

  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}


@media (hover: hover) {

  .erp-stat-card:hover {

    transform:
      translateY(-3px);

    border-color:
      var(--brand-border-strong);

    box-shadow:
      0 10px 26px rgba(36, 59, 99, 0.10);
  }
}


/* =========================================================
   18. STAT ICON
========================================================= */

.erp-stat-icon {

  display: flex;

  align-items: center;
  justify-content: center;

  width: 46px;
  height: 46px;

  flex: 0 0 46px;

  border-radius: 12px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size: 11px !important;
  font-weight: 800;

  letter-spacing: 0.4px;
}


.erp-stat-card.overview-tone-1
.erp-stat-icon {

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;
}


.erp-stat-card.overview-tone-2
.erp-stat-icon {

  background:
    var(--brand-soft-secondary);

  color:
    var(--brand-secondary) !important;
}


.erp-stat-card.overview-tone-3
.erp-stat-icon {

  background:
    var(--brand-soft-accent);

  color:
    var(--brand-accent) !important;
}


.erp-stat-card.overview-tone-4
.erp-stat-icon {

  background:
    var(--brand-soft-purple);

  color:
    var(--brand-purple) !important;
}


/* =========================================================
   19. STAT INFO
========================================================= */

.erp-stat-info {

  display: flex;

  flex-direction: column;

  gap: 3px;

  min-width: 0;

  color:
    var(--brand-text) !important;
}


.erp-stat-value,
.erp-stat-card .erp-stat-value {

  color:
    var(--brand-text) !important;

  font-size:
    20px !important;

  font-weight:
    800 !important;

  line-height: 1.3;

  direction: ltr;
}


.erp-stat-label,
.erp-stat-card .erp-stat-label {

  color:
    var(--brand-text) !important;

  font-size:
    12px !important;

  font-weight:
    600 !important;

  line-height: 1.45;
}


/* =========================================================
   20. QUICK ACTIONS
   تم إبقاء تصميم الاختصارات كما كان
========================================================= */

.erp-quick-actions {

  margin-bottom: 24px;
}


/* =========================================================
   21. QUICK ACTIONS GRID
========================================================= */

.erp-quick-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 12px;
}


/* =========================================================
   22. QUICK BUTTON
========================================================= */

.erp-quick-btn {

  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 48px;

  padding:
    11px 14px;

  border:
    1px solid var(--brand-border);

  border-radius: 10px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 15px;
  font-weight: 700;

  line-height: 1.4;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}


.erp-quick-btn:nth-child(1) {

  background:
    var(--brand-soft);
}


.erp-quick-btn:nth-child(2) {

  background:
    var(--brand-soft-secondary);
}


.erp-quick-btn:nth-child(3) {

  background:
    var(--brand-soft-accent);
}


.erp-quick-btn:nth-child(4) {

  background:
    var(--brand-soft-purple);
}


.erp-quick-btn,
.erp-quick-btn .erp-quick-label {

  color:
    var(--brand-primary) !important;
}


@media (hover: hover) {

  .erp-quick-btn:hover {

    transform:
      translateY(-2px);

    color:
      var(--brand-secondary) !important;

    border-color:
      var(--brand-secondary);

    background:
      rgba(15, 132, 181, 0.10);

    box-shadow:
      0 6px 16px rgba(56, 103, 174, 0.12);
  }
}


.erp-quick-btn:active {

  transform:
    scale(0.98);
}


.erp-quick-label {

  width: 100%;

  white-space: normal;

  text-align: center;
}


/* =========================================================
   23. MODULE SECTION
========================================================= */

.erp-module-section {

  margin-top: 24px;
}


/* =========================================================
   24. REPORT CARDS GRID
========================================================= */

.erp-dashboard-grid {

  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  align-items: start;

  gap: 16px;

  width: 100%;

  overflow: visible;
}


/* =========================================================
   25. REPORT CARD
========================================================= */

.erp-card {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);

  position: relative;

  z-index: 1;

  min-width: 0;

  min-height: 74px;
  max-height: 74px;

  padding:
    0 16px;

  overflow: hidden;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.95);

  color:
    var(--brand-text) !important;

  box-shadow:
    0 5px 16px rgba(36, 59, 99, 0.06);

  transition:
    max-height 0.4s ease,
    transform 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease,
    padding-bottom 0.28s ease;
}


.erp-card::before {

  content: "";

  position: absolute;

  inset: 0;

  z-index: 0;

  background:
    var(--erp-soft);

  opacity: 0;

  pointer-events: none;

  transition:
    opacity 0.25s ease;
}


.erp-card::after {

  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  z-index: 4;

  width: 0;
  height: 3px;

  background:
    var(--erp-accent);

  transition:
    width 0.3s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-card::after {

  right: auto;
  left: 0;
}


/* =========================================================
   26. CARD BRAND TONES
========================================================= */

.erp-card.tone-0 {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);
}


.erp-card.tone-1 {

  --erp-accent:
    var(--brand-secondary);

  --erp-soft:
    var(--brand-soft-secondary);
}


.erp-card.tone-2 {

  --erp-accent:
    var(--brand-accent);

  --erp-soft:
    var(--brand-soft-accent);
}


.erp-card.tone-3 {

  --erp-accent:
    var(--brand-purple);

  --erp-soft:
    var(--brand-soft-purple);
}


.erp-card.tone-4 {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);
}


/* =========================================================
   27. CARD OPEN
========================================================= */

.erp-card.is-open {

  z-index: 30;

  max-height: 590px;

  padding-bottom: 15px;

  border-color:
    var(--erp-accent);

  transform:
    translateY(-5px);

  box-shadow:
    0 18px 40px rgba(36, 59, 99, 0.14);
}


.erp-card.is-open::before {

  opacity: 1;
}


.erp-card.is-open::after {

  width: 100%;
}





/* =========================================================
   28. CARD HEADING
========================================================= */

.erp-card-heading {

  position: relative;

  z-index: 2;

  display: flex;
  align-items: center;

  gap: 8px;

  width: 100%;
  height: 72px;

  margin: 0;
  padding: 0;

  border: 0;
  border-bottom:
    1px solid transparent;

  outline: none;

  background:
    transparent;

  color:
    var(--brand-text) !important;

  font-family: inherit;

  text-align: inherit;

  cursor: pointer;

  transition:
    border-color 0.22s ease,
    margin-bottom 0.22s ease;
}


.erp-card.is-open
.erp-card-heading {

  margin-bottom: 10px;

  border-bottom-color:
    var(--brand-border);
}





/* =========================================================
   29. CARD ICON
========================================================= */

.erp-icon {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 34px;
  height: 34px;

  flex:
    0 0 34px;

  border-radius:
    9px;

  background:
    var(--erp-soft);

  font-size:
    17px;
}


/* =========================================================
   30. CARD TITLE
========================================================= */

.erp-card-title,
.erp-card .erp-card-title {

  flex: 1;

  min-width: 0;

  color:
    var(--brand-text) !important;

  font-size:
    16px;

  font-weight:
    800;

  line-height:
    1.5;
}


/* =========================================================
   31. CARD CHEVRON
========================================================= */

.erp-card-chevron {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  flex:
    0 0 28px;

  border-radius:
    8px;

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;

  font-size:
    17px;

  transition:
    transform 0.22s ease;
}


.erp-card.is-open
.erp-card-chevron {

  transform:
    rotate(180deg);
}





/* =========================================================
   32. CARD LINKS
========================================================= */

.erp-card-links {

  position: relative;

  z-index: 2;

  display: grid;

  gap: 5px;

  max-height: 0;

  margin: 0;
  padding: 0;

  overflow: hidden;

  opacity: 0;
  visibility: hidden;

  pointer-events: none;

  transform:
    translateY(-8px);

  transition:
    max-height 0.38s ease,
    opacity 0.2s ease,
    visibility 0.2s ease,
    transform 0.28s ease;
}


.erp-card.is-open
.erp-card-links {

  max-height: 480px;

  overflow-y: auto;

  opacity: 1;
  visibility: visible;

  pointer-events: auto;

  transform:
    translateY(0);
}





/* =========================================================
   33. LINK ROW
========================================================= */

.erp-link-row {

  display: flex;

  align-items: center;

  gap: 6px;

  width: 100%;
}


/* =========================================================
   34. CARD LINK
========================================================= */

.erp-link {

  display: flex;

  align-items: center;

  gap: 7px;

  flex: 1;

  min-width: 0;
  min-height: 36px;

  padding:
    7px 10px;

  border:
    1px solid transparent;

  border-radius:
    8px;

  outline: none;

  background:
    transparent;

  color:
    var(--brand-text) !important;

  font-family: inherit;

  font-size:
    13px;

  font-weight:
    500;

  line-height:
    1.45;

  text-align:
    inherit;

  cursor: pointer;

  transition:
    background 0.16s ease,
    color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;
}


.erp-link-text {

  flex: 1;

  min-width: 0;

  color:
    inherit !important;
}


.erp-link:hover,
.erp-link:focus {

  border-color:
    var(--brand-border);

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;
}


.erp-dashboard-rtl
.erp-link:hover,

.erp-dashboard-rtl
.erp-link:focus {

  transform:
    translateX(-3px);
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:hover,

.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:focus {

  transform:
    translateX(3px);
}


/* =========================================================
   35. LINK ARROW
========================================================= */

.erp-link-arrow {

  flex:
    0 0 auto;

  color:
    var(--erp-accent) !important;

  font-size:
    13px;

  font-weight:
    800;

  opacity: 0;

  transition:
    opacity 0.16s ease;
}


.erp-link:hover
.erp-link-arrow,

.erp-link:focus
.erp-link-arrow {

  opacity: 1;
}


/* =========================================================
   36. DETAILS BUTTON
========================================================= */

.erp-info-link {

  flex:
    0 0 auto;

  padding:
    5px 10px;

  border:
    1px solid var(--brand-border);

  border-radius:
    7px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family:
    inherit;

  font-size:
    12px;

  font-weight:
    600;

  cursor: pointer;

  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}


.erp-info-link:hover {

  border-color:
    var(--brand-primary);

  background:
    rgba(56, 103, 174, 0.13);

  color:
    var(--brand-primary) !important;
}


/* =========================================================
   37. SCROLLBAR
========================================================= */

.erp-card-links::-webkit-scrollbar {

  width: 5px;
}


.erp-card-links::-webkit-scrollbar-track {

  background:
    transparent;
}


.erp-card-links::-webkit-scrollbar-thumb {

  border-radius:
    10px;

  background:
    var(--brand-primary);
}


/* =========================================================
   38. FOOTER
========================================================= */

.erp-footer {

  --footer-font-size:
    15px;

  margin-top:
    34px;

  padding:
    20px 12px 4px;

  border-top:
    1px solid var(--brand-border);

  color:
    var(--brand-text);
}


.erp-footer-inner {

  display: flex;

  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap:
    10px 22px;

  width: 100%;
}


.erp-footer-item {

  display: flex;

  align-items: center;

  gap: 7px;

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600;

  line-height:
    1.6;
}


.erp-footer-icon {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  color:
    var(--brand-primary) !important;

  font-size:
    17px !important;

  line-height:
    1;
}


.erp-footer-label {

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    700 !important;
}


.erp-footer-link {

  color:
    var(--brand-primary) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600 !important;

  text-decoration: none;

  transition:
    color 0.18s ease;
}


.erp-footer-link:hover {

  color:
    var(--brand-secondary) !important;

  text-decoration:
    underline;
}


.erp-footer-sep {

  color:
    var(--brand-border-strong) !important;

  font-size:
    20px;

  font-weight:
    300;

  line-height:
    1;
}


/* =========================================================
   39. MODAL OVERLAY
========================================================= */

.erp-modal-overlay {

  position: fixed;

  inset: 0;

  z-index:
    99999 !important;

  display: flex;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background:
    rgba(12, 27, 54, 0) !important;

  transition:
    background 0.28s ease;
}


.erp-modal-overlay.is-visible {

  background:
    rgba(12, 27, 54, 0.52) !important;
}


/* =========================================================
   40. MODAL BOX
========================================================= */

.erp-modal-box {

  position: relative;

  width: 100%;

  max-width: 480px;
  max-height: 85vh;

  padding:
    28px 24px;

  overflow-y: auto;

  border:
    1px solid var(--brand-border);

  border-radius:
    16px;

  background:
    #ffffff !important;

  box-shadow:
    0 24px 64px rgba(12, 27, 54, 0.28) !important;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.97);

  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}


.erp-modal-overlay.is-visible
.erp-modal-box {

  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}


/* =========================================================
   41. MODAL CLOSE
========================================================= */

.erp-modal-close {

  position: absolute;

  top: 12px;

  display: flex;

  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: 0;

  border-radius:
    8px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size:
    15px;

  cursor:
    pointer;
}


[dir="rtl"]
.erp-modal-close {

  left: 12px;
}


[dir="ltr"]
.erp-modal-close {

  right: 12px;
}


/* =========================================================
   42. MODAL CONTENT
========================================================= */

.erp-modal-header {

  display: flex;

  align-items: center;

  gap: 11px;

  margin-bottom:
    15px;
}


.erp-modal-icon {

  font-size:
    28px;

  line-height:
    1;
}


.erp-modal-title {

  margin: 0;

  color:
    var(--brand-text) !important;

  font-size:
    18px;

  font-weight:
    800;
}


.erp-modal-summary {

  margin:
    0 0 16px;

  color:
    var(--brand-text) !important;

  font-size:
    13.5px;

  line-height:
    1.75;
}


/* =========================================================
   43. MODAL STEPS BUTTON
========================================================= */

.erp-modal-toggle-steps {

  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    8px 16px;

  border:
    1px solid var(--brand-primary);

  border-radius:
    9px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family:
    inherit;

  font-size:
    12.5px;

  font-weight:
    700;

  cursor:
    pointer;
}


.erp-modal-toggle-steps:hover {

  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   44. MODAL STEPS
========================================================= */

.erp-modal-steps {

  max-height: 0;

  overflow: hidden;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {

  max-height: 500px;

  opacity: 1;

  margin-top:
    15px;
}


.erp-modal-steps-list {

  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {

  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

  color:
    var(--brand-text) !important;

  font-size:
    12.5px;

  line-height:
    1.65;
}


.erp-modal-steps-list li:last-child {

  border-bottom: 0;
}


.erp-modal-steps-list li::before {

  content:
    counter(step-counter);

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  margin-inline-end:
    9px;

  border-radius:
    50%;

  background:
    var(--brand-primary);

  color:
    #ffffff;

  font-size:
    10px;

  font-weight:
    800;
}


/* =========================================================
   45. DARK MODE
========================================================= */

[data-theme="dark"]
.erp-dashboard-wrapper,

html[data-theme="dark"]
.erp-dashboard-wrapper {

  --brand-text:
    #E9EEF7;

  --brand-muted:
    #A7B2C5;

  --brand-border:
    rgba(15, 132, 181, 0.22);

  --brand-border-strong:
    rgba(15, 132, 181, 0.40);
}


/*
   في الوضع الداكن نقلل وضوح Pattern
*/

[data-theme="dark"]
.erp-dashboard-wrapper::before,

html[data-theme="dark"]
.erp-dashboard-wrapper::before {

  opacity: 0.025;
}


[data-theme="dark"]
.erp-cycle-container,

html[data-theme="dark"]
.erp-cycle-container,

[data-theme="dark"]
.erp-overview-container,

html[data-theme="dark"]
.erp-overview-container,

[data-theme="dark"]
.erp-cycle-card,

html[data-theme="dark"]
.erp-cycle-card,

[data-theme="dark"]
.erp-card,

html[data-theme="dark"]
.erp-card,

[data-theme="dark"]
.erp-stat-card,

html[data-theme="dark"]
.erp-stat-card {

  background:
    rgba(32, 36, 44, 0.95);

  box-shadow:
    0 7px 22px rgba(0, 0, 0, 0.18);
}


[data-theme="dark"]
.erp-modal-box,

html[data-theme="dark"]
.erp-modal-box {

  background:
    var(--fg-color, #20242c) !important;
}


/* =========================================================
   46. LARGE TABLET
========================================================= */

@media (max-width: 1250px) {

  .erp-cycle-grid {

    grid-template-columns:
      repeat(4, minmax(0, 1fr));
  }


  .erp-cycle-arrow {

    display: none;
  }


  /*
     نصغر الـ Pattern قليلاً
  */

  .erp-dashboard-wrapper::before {

    -webkit-mask-size:
      155px auto;

    mask-size:
      155px auto;
  }
}


/* =========================================================
   47. TABLET
========================================================= */

@media (max-width: 1050px) {

  .erp-dashboard-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }
}


/* =========================================================
   48. SMALL TABLET
========================================================= */

@media (max-width: 850px) {

  .erp-cycle-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }


  .erp-overview-container
  .erp-stats-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }


  .erp-quick-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }
}


/* =========================================================
   49. MOBILE
========================================================= */

@media (max-width: 650px) {

  .erp-dashboard-wrapper {

    padding:
      8px 8px 26px;
  }


  /*
     نحافظ على Pattern في الجوال
     لكن نصغره ونخففه
  */

  .erp-dashboard-wrapper::before {

    -webkit-mask-size:
      115px auto;

    mask-size:
      115px auto;

    opacity:
      0.025;
  }


  /* دورة المشتريات */

  .erp-cycle-container {

    padding:
      12px;
  }


  .erp-cycle-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap:
      8px;
  }


  .erp-cycle-card {

    min-height:
      155px;

    padding:
      13px 8px;
  }


  .erp-cycle-number {

    width:
      36px;

    height:
      36px;

    flex-basis:
      36px;

    margin-bottom:
      10px;

    font-size:
      15px;
  }


  .erp-cycle-card-title {

    font-size:
      12px;
  }


  .erp-cycle-description {

    font-size:
      9.5px;

    line-height:
      1.55;
  }


  /* نظرة عامة */

  .erp-overview-container {

    padding:
      12px;
  }


  .erp-overview-container
  .erp-stats-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap:
      9px;
  }


  .erp-stat-card {

    min-height:
      76px;

    padding:
      11px;

    gap:
      8px;
  }


  .erp-stat-icon {

    width:
      36px;

    height:
      36px;

    flex-basis:
      36px;

    font-size:
      9px !important;
  }


  .erp-stat-value,
  .erp-stat-card .erp-stat-value {

    font-size:
      15px !important;
  }


  .erp-stat-label,
  .erp-stat-card .erp-stat-label {

    font-size:
      10px !important;
  }


  /* الاختصارات */

  .erp-quick-grid {

    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;

    gap:
      8px;
  }


  .erp-quick-btn {

    min-height:
      43px;

    padding:
      9px 7px;

    font-size:
      11.5px;
  }


  /* التقارير */

  .erp-dashboard-grid {

    grid-template-columns:
      1fr !important;

    gap:
      11px;
  }


  .erp-card.is-open {

    transform:
      translateY(-2px);
  }


  /* الفوتر */

  .erp-footer {

    --footer-font-size:
      13px;

    margin-top:
      26px;

    padding-top:
      16px;
  }


  .erp-footer-inner {

    flex-direction:
      column;

    gap:
      8px;
  }


  .erp-footer-item {

    justify-content:
      center;
  }


  .erp-footer-icon {

    font-size:
      15px !important;
  }


  .erp-footer-sep {

    display:
      none;
  }


  /* المودال */

  .erp-modal-overlay {

    align-items:
      flex-end;

    padding:
      10px;
  }


  .erp-modal-box {

    max-height:
      82vh;

    padding:
      22px 17px;

    border-radius:
      16px 16px 0 0;
  }
}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: none !important;
}

script:
(() => {

  /* =========================================================
     MUBTKIR ERP — EXPENSE CLAIMS WORKSPACE
     لوحة تحكم مطالبات المصروفات
  ========================================================= */

  const root =
    root_element.querySelector("[data-erp-dashboard]");

  const cycleSection =
    root_element.querySelector("[data-purchase-cycle]");

  const statsSection =
    root_element.querySelector("[data-stats-section]");

  const quickActions =
    root_element.querySelector("[data-quick-actions]");

  const content =
    root_element.querySelector("[data-dashboard-content]");

  const footerEl =
    root_element.querySelector("[data-dashboard-footer]");

  if (!root) return;


  /* =========================================================
     1. LANGUAGE
  ========================================================= */

  const langValue =
    window.frappe?.boot?.lang ||
    document.documentElement.lang ||
    "en";

  const isArabic =
    String(langValue)
      .toLowerCase()
      .startsWith("ar");

  root.setAttribute(
    "dir",
    isArabic ? "rtl" : "ltr"
  );


  /* =========================================================
     2. HELPERS
  ========================================================= */

  function escapeHtml(value) {

    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }


  function formatNumber(value) {

    return (
      parseFloat(value) || 0
    ).toLocaleString("en-US");
  }


  function getMonthStart() {

    const d = new Date();

    const year =
      d.getFullYear();

    const month =
      String(
        d.getMonth() + 1
      ).padStart(2, "0");

    return `${year}-${month}-01`;
  }


  function safeCount(
    doctype,
    filters = {}
  ) {

    return new Promise(resolve => {

      try {

        frappe.call({

          method:
            "frappe.client.get_count",

          args: {
            doctype,
            filters
          },

          callback: r => {

            resolve(
              r?.message || 0
            );

          },

          error: () =>
            resolve(0)

        });

      } catch (e) {

        console.error(
          "Expense Claim Count Error:",
          doctype,
          e
        );

        resolve(0);

      }

    });

  }


  function newDoc(doctype) {

    try {

      frappe.new_doc(
        doctype
      );

    } catch (e) {

      console.error(
        "Expense Claim New Doc Error:",
        doctype,
        e
      );

    }

  }


  /* =========================================================
     3. ROUTING
  ========================================================= */

  const reportNames =
    new Set([
      "Unpaid Expense Claim",
      "Employee Advance Summary"
    ]);


  const treeDocs =
    new Set([
      "Cost Center"
    ]);


  function openRoute(name) {

    try {

      if (
        reportNames.has(name)
      ) {

        frappe.set_route(
          "query-report",
          name
        );

        return;
      }


      if (
        treeDocs.has(name)
      ) {

        frappe.set_route(
          "Tree",
          name
        );

        return;
      }


      frappe.set_route(
        "List",
        name
      );

    } catch (e) {

      console.error(
        "Expense Claim Route Error:",
        name,
        e
      );

    }

  }


  /* =========================================================
     4. EXPENSE CLAIM CYCLE
  ========================================================= */

  const cycleCards = [

    {
      step: 1,

      action: "new",
      doctype: "Expense Claim",

      labelAr:
        "إنشاء المطالبة",

      labelEn:
        "Create Expense Claim",

      descriptionAr:
        "إنشاء مطالبة مصروف جديدة للموظف.",

      descriptionEn:
        "Create a new employee expense claim."
    },


    {
      step: 2,

      action: "route",
      doctype: "Expense Claim",

      labelAr:
        "إضافة المصروفات",

      labelEn:
        "Add Expenses",

      descriptionAr:
        "إضافة أنواع المصروفات والمبالغ والتواريخ.",

      descriptionEn:
        "Add expense types, amounts and dates."
    },


    {
      step: 3,

      action: "route",
      doctype: "Expense Claim",

      labelAr:
        "إرفاق المستندات",

      labelEn:
        "Attach Documents",

      descriptionAr:
        "إرفاق الفواتير والإيصالات والمستندات المؤيدة.",

      descriptionEn:
        "Attach invoices, receipts and supporting documents."
    },


    {
      step: 4,

      action: "route",
      doctype: "Expense Claim",

      labelAr:
        "المراجعة والاعتماد",

      labelEn:
        "Review & Approve",

      descriptionAr:
        "مراجعة المطالبة واعتمادها من المسؤول.",

      descriptionEn:
        "Review and approve the employee expense claim."
    },


    {
      step: 5,

      action: "payment-selector",

      labelAr:
        "الدفع والتسوية",

      labelEn:
        "Payment & Settlement",

      descriptionAr:
        "تسجيل دفع المطالبة أو تسويتها محاسبياً.",

      descriptionEn:
        "Pay or financially settle the approved claim."
    },


    {
      step: 6,

      action: "route",
      doctype: "Expense Claim",

      labelAr:
        "إغلاق المطالبة",

      labelEn:
        "Close Claim",

      descriptionAr:
        "متابعة المطالبة حتى اكتمال السداد والتسوية.",

      descriptionEn:
        "Track the claim until reimbursement is completed."
    }

  ];


  /* =========================================================
     5. OVERVIEW
  ========================================================= */

  const statsCards = [

    {
      id:
        "open-claims",

      short:
        "OPEN",

      labelAr:
        "المطالبات المفتوحة",

      labelEn:
        "Open Claims",

      fetch: () =>
        safeCount(
          "Expense Claim",
          {
            docstatus: 0
          }
        )
    },


    {
      id:
        "approved-claims",

      short:
        "APP",

      labelAr:
        "المطالبات المعتمدة",

      labelEn:
        "Approved Claims",

      fetch: () =>
        safeCount(
          "Expense Claim",
          {
            docstatus: 1
          }
        )
    },


    {
      id:
        "unpaid-claims",

      short:
        "DUE",

      labelAr:
        "المطالبات غير المدفوعة",

      labelEn:
        "Unpaid Claims",

      fetch: () =>
        safeCount(
          "Expense Claim",
          {
            docstatus: 1,

            status: [
              "!=",
              "Paid"
            ]
          }
        )
    },


    {
      id:
        "month-claims",

      short:
        "MTH",

      labelAr:
        "مطالبات هذا الشهر",

      labelEn:
        "Claims This Month",

      fetch: () =>
        safeCount(
          "Expense Claim",
          {
            creation: [
              ">=",
              getMonthStart()
            ]
          }
        )
    }

  ];


  /* =========================================================
     6. QUICK ACTIONS
  ========================================================= */

  const quickButtons = [

    {
      doctype:
        "Expense Claim",

      labelAr:
        "مطالبة مصروف جديدة",

      labelEn:
        "New Expense Claim"
    },


    {
      doctype:
        "Expense Claim Type",

      labelAr:
        "نوع مصروف جديد",

      labelEn:
        "New Expense Type"
    },


    {
      doctype:
        "Employee Advance",

      labelAr:
        "سلفة موظف جديدة",

      labelEn:
        "New Employee Advance"
    },


    {
      doctype:
        "Payment Entry",

      labelAr:
        "دفعة جديدة",

      labelEn:
        "New Payment Entry"
    }

  ];


  /* =========================================================
     7. LOWER CARDS
  ========================================================= */

  const cards = [

    {
      titleAr:
        "مطالبات المصروفات",

      titleEn:
        "Expense Claims",

      icon:
        "🧾",

      links: [
        "Expense Claim"
      ]
    },


    {
      titleAr:
        "أنواع المصروفات",

      titleEn:
        "Expense Types",

      icon:
        "🏷️",

      links: [
        "Expense Claim Type"
      ]
    },


    {
      titleAr:
        "سلف الموظفين",

      titleEn:
        "Employee Advances",

      icon:
        "💰",

      links: [
        "Employee Advance"
      ]
    },


    {
      titleAr:
        "القيود والمدفوعات",

      titleEn:
        "Payments & Accounting",

      icon:
        "💳",

      links: [
        "Payment Entry",
        "Journal Entry"
      ]
    },


    {
      titleAr:
        "الموظفون",

      titleEn:
        "Employees",

      icon:
        "👤",

      links: [
        "Employee"
      ]
    },


    {
      titleAr:
        "مراكز التكلفة",

      titleEn:
        "Cost Centers",

      icon:
        "🎯",

      links: [
        "Cost Center"
      ]
    },


    {
      titleAr:
        "المشاريع",

      titleEn:
        "Projects",

      icon:
        "🏗️",

      links: [
        "Project"
      ]
    },


    {
      titleAr:
        "السفر والمصروفات",

      titleEn:
        "Travel & Expenses",

      icon:
        "✈️",

      links: [
        "Travel Request"
      ]
    },


    {
      titleAr:
        "التقارير",

      titleEn:
        "Reports",

      icon:
        "📊",

      links: [
        "Unpaid Expense Claim",
        "Employee Advance Summary"
      ]
    }

  ];


  /* =========================================================
     8. TRANSLATIONS
  ========================================================= */

  const translations = {

    "Expense Claim":
      "مطالبة المصروف",

    "Expense Claim Type":
      "نوع المصروف",

    "Employee Advance":
      "سلفة الموظف",

    "Payment Entry":
      "سند الدفع",

    "Journal Entry":
      "قيد اليومية",

    "Employee":
      "الموظف",

    "Cost Center":
      "مركز التكلفة",

    "Project":
      "المشروع",

    "Travel Request":
      "طلب سفر",

    "Unpaid Expense Claim":
      "مطالبات المصروفات غير المدفوعة",

    "Employee Advance Summary":
      "ملخص سلف الموظفين"

  };


  function translate(name) {

    if (!isArabic)
      return name;

    return (
      translations[name] ||
      name
    );

  }


  /* =========================================================
     9. PAYMENT SELECTOR
  ========================================================= */

  function showPaymentSelector() {

    const overlay =
      document.createElement("div");

    overlay.className =
      "erp-modal-overlay";

    overlay.setAttribute(
      "dir",
      isArabic
        ? "rtl"
        : "ltr"
    );


    overlay.innerHTML = `

      <div class="erp-modal-box">

        <button
          type="button"
          class="erp-modal-close"
          data-expense-close
        >
          ✕
        </button>


        <div class="erp-modal-header">

          <span class="erp-modal-icon">
            💳
          </span>

          <h3 class="erp-modal-title">

            ${
              isArabic
                ? "الدفع والتسوية"
                : "Payment & Settlement"
            }

          </h3>

        </div>


        <div
          class="erp-quick-grid"
          style="
            margin-top:18px;
            grid-template-columns:
            repeat(2,minmax(0,1fr)) !important;
          "
        >

          <button
            type="button"
            class="erp-quick-btn"
            data-expense-payment="Payment Entry"
          >
            ${
              isArabic
                ? "سند دفع"
                : "Payment Entry"
            }
          </button>


          <button
            type="button"
            class="erp-quick-btn"
            data-expense-payment="Journal Entry"
          >
            ${
              isArabic
                ? "قيد يومية"
                : "Journal Entry"
            }
          </button>

        </div>

      </div>

    `;


    root.appendChild(
      overlay
    );


    requestAnimationFrame(() => {

      overlay.classList.add(
        "is-visible"
      );

    });


    overlay
      .querySelector(
        "[data-expense-close]"
      )
      ?.addEventListener(
        "click",
        () => overlay.remove()
      );


    overlay.addEventListener(
      "click",
      event => {

        if (
          event.target === overlay
        ) {

          overlay.remove();

        }

      }
    );


    overlay
      .querySelectorAll(
        "[data-expense-payment]"
      )
      .forEach(button => {

        button.addEventListener(
          "click",
          () => {

            const doctype =
              button.dataset.expensePayment;

            overlay.remove();

            openRoute(
              doctype
            );

          }
        );

      });

  }


  /* =========================================================
     10. RENDER CYCLE
  ========================================================= */

  function renderCycle() {

    if (!cycleSection)
      return;


    cycleSection.innerHTML = `

      <section class="erp-cycle-container">

        <h2
          class="
            erp-section-title
            erp-cycle-title
          "
        >
          ${
            isArabic
              ? "دورة مطالبات المصروفات"
              : "Expense Claim Cycle"
          }
        </h2>


        <div
          class="erp-cycle-grid"
          style="
            grid-template-columns:
            repeat(
              ${cycleCards.length},
              minmax(0,1fr)
            );
          "
        >

          ${cycleCards
            .map(
              (card, index) => `

                <div class="erp-cycle-item">

                  <button
                    type="button"
                    class="
                      erp-cycle-card
                      cycle-tone-${(index % 4) + 1}
                    "
                    data-expense-cycle="${index}"
                  >

                    <span
                      class="erp-cycle-number"
                    >
                      ${card.step}
                    </span>


                    <span
                      class="erp-cycle-card-title"
                    >

                      ${escapeHtml(
                        isArabic
                          ? card.labelAr
                          : card.labelEn
                      )}

                    </span>


                    <span
                      class="erp-cycle-description"
                    >

                      ${escapeHtml(
                        isArabic
                          ? card.descriptionAr
                          : card.descriptionEn
                      )}

                    </span>

                  </button>


                  ${
                    index <
                    cycleCards.length - 1

                      ? `
                        <span class="erp-cycle-arrow">
                          ${isArabic ? "←" : "→"}
                        </span>
                      `

                      : ""
                  }

                </div>

              `
            )
            .join("")}

        </div>

      </section>

    `;


    cycleSection.addEventListener(
      "click",
      event => {

        const element =
          event.target.closest(
            "[data-expense-cycle]"
          );


        if (!element)
          return;


        const card =
          cycleCards[
            Number(
              element.dataset.expenseCycle
            )
          ];


        if (!card)
          return;


        if (
          card.action === "new"
        ) {

          newDoc(
            card.doctype
          );

          return;
        }


        if (
          card.action ===
          "payment-selector"
        ) {

          showPaymentSelector();

          return;
        }


        openRoute(
          card.doctype
        );

      }
    );

  }


  /* =========================================================
     11. RENDER STATS
  ========================================================= */

  function renderStats() {

    if (!statsSection)
      return;


    statsSection.innerHTML = `

      <section class="erp-overview-container">

        <h2 class="erp-section-title">

          ${
            isArabic
              ? "نظرة عامة"
              : "Overview"
          }

        </h2>


        <div class="erp-stats-grid">

          ${statsCards
            .map(
              (card, index) => `

                <div
                  class="
                    erp-stat-card
                    overview-tone-${index + 1}
                  "
                >

                  <div class="erp-stat-icon">
                    ${escapeHtml(card.short)}
                  </div>


                  <div class="erp-stat-info">

                    <span
                      class="erp-stat-value"
                      data-expense-stat="${card.id}"
                    >
                      0
                    </span>


                    <span
                      class="erp-stat-label"
                    >

                      ${escapeHtml(
                        isArabic
                          ? card.labelAr
                          : card.labelEn
                      )}

                    </span>

                  </div>

                </div>

              `
            )
            .join("")}

        </div>

      </section>

    `;


    statsCards.forEach(
      card => {

        Promise
          .resolve()
          .then(
            () => card.fetch()
          )
          .then(
            value => {

              const element =
                statsSection.querySelector(
                  `[data-expense-stat="${card.id}"]`
                );


              if (element) {

                element.textContent =
                  formatNumber(value);

              }

            }
          )
          .catch(
            error => {

              console.error(
                "Expense Claim Stat Error:",
                card.id,
                error
              );

            }
          );

      }
    );

  }


  /* =========================================================
     12. QUICK ACTIONS
  ========================================================= */

  function renderQuickActions() {

    if (!quickActions)
      return;


    quickActions.innerHTML = `

      <h2 class="erp-section-title">

        ${
          isArabic
            ? "اختصارات سريعة"
            : "Quick Actions"
        }

      </h2>


      <div class="erp-quick-grid">

        ${quickButtons
          .map(
            (button, index) => `

              <button
                type="button"
                class="erp-quick-btn"
                data-expense-quick="${index}"
              >

                <span
                  class="erp-quick-label"
                >

                  ${escapeHtml(
                    isArabic
                      ? button.labelAr
                      : button.labelEn
                  )}

                </span>

              </button>

            `
          )
          .join("")}

      </div>

    `;


    quickActions.addEventListener(
      "click",
      event => {

        const element =
          event.target.closest(
            "[data-expense-quick]"
          );


        if (!element)
          return;


        const button =
          quickButtons[
            Number(
              element.dataset.expenseQuick
            )
          ];


        if (!button)
          return;


        newDoc(
          button.doctype
        );

      }
    );

  }


  /* =========================================================
     13. RENDER CARDS
  ========================================================= */

  function renderCards() {

    if (!content)
      return;


    const cardsHtml =
      cards
        .map(
          (card, index) => {

            const links =
              card.links
                .map(
                  item => `

                    <div class="erp-link-row">

                      <button
                        type="button"
                        class="erp-link"
                        data-expense-route="${escapeHtml(item)}"
                      >

                        <span class="erp-link-text">
                          ${escapeHtml(translate(item))}
                        </span>


                        <span class="erp-link-arrow">
                          ${isArabic ? "←" : "→"}
                        </span>

                      </button>

                    </div>

                  `
                )
                .join("");


            return `

              <article
                class="
                  erp-card
                  tone-${index % 5}
                "
                data-expense-card
              >

                <button
                  type="button"
                  class="erp-card-heading"
                  data-expense-toggle
                  aria-expanded="false"
                >

                  <span class="erp-icon">
                    ${card.icon}
                  </span>


                  <span class="erp-card-title">

                    ${escapeHtml(
                      isArabic
                        ? card.titleAr
                        : card.titleEn
                    )}

                  </span>


                  <span class="erp-card-chevron">
                    ⌄
                  </span>

                </button>


                <div class="erp-card-links">
                  ${links}
                </div>

              </article>

            `;

          }
        )
        .join("");


    content.innerHTML = `

      <section class="erp-module-section">

        <h2 class="erp-section-title">

          ${
            isArabic
              ? "البيانات الرئيسية والتقارير"
              : "Reports & Masters"
          }

        </h2>


        <div class="erp-dashboard-grid">
          ${cardsHtml}
        </div>

      </section>

    `;


    content.addEventListener(
      "click",
      event => {

        const routeButton =
          event.target.closest(
            "[data-expense-route]"
          );


        if (routeButton) {

          event.preventDefault();

          openRoute(
            routeButton.dataset.expenseRoute
          );

          return;
        }


        const toggle =
          event.target.closest(
            "[data-expense-toggle]"
          );


        if (!toggle)
          return;


        const selectedCard =
          toggle.closest(
            "[data-expense-card]"
          );


        if (!selectedCard)
          return;


        const shouldOpen =
          !selectedCard.classList.contains(
            "is-open"
          );


        content
          .querySelectorAll(
            "[data-expense-card]"
          )
          .forEach(card => {

            if (
              card !== selectedCard
            ) {

              card.classList.remove(
                "is-open"
              );

            }

          });


        selectedCard.classList.toggle(
          "is-open",
          shouldOpen
        );

      }
    );

  }


  /* =========================================================
     14. FOOTER
  ========================================================= */

  function renderFooter() {

    if (!footerEl)
      return;


    footerEl.innerHTML = `

      <div class="erp-footer-inner">

        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            ☎
          </span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? "الهاتف الموحد:"
                : "Phone:"
            }

          </span>

          <a
            href="tel:0115110455"
            class="erp-footer-link"
            dir="ltr"
          >
            0115110455
          </a>

        </div>


        <span class="erp-footer-sep">
          |
        </span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            ✉
          </span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? "البريد الإلكتروني:"
                : "Email:"
            }

          </span>

          <a
            href="mailto:sales@mubtkir.com"
            class="erp-footer-link"
          >
            sales@mubtkir.com
          </a>

        </div>


        <span class="erp-footer-sep">
          |
        </span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            ◎
          </span>

          <span class="erp-footer-label">

            ${
              isArabic
                ? "الموقع:"
                : "Website:"
            }

          </span>

          <a
            href="https://www.mubtkir.com"
            class="erp-footer-link"
            target="_blank"
            rel="noopener"
          >
            www.mubtkir.com
          </a>

        </div>

      </div>

    `;

  }


  /* =========================================================
     15. INIT
  ========================================================= */

  try {
    renderCycle();
  } catch (e) {
    console.error(
      "Expense Claim Cycle Error:",
      e
    );
  }


  try {
    renderStats();
  } catch (e) {
    console.error(
      "Expense Claim Stats Error:",
      e
    );
  }


  try {
    renderQuickActions();
  } catch (e) {
    console.error(
      "Expense Claim Quick Actions Error:",
      e
    );
  }


  try {
    renderCards();
  } catch (e) {
    console.error(
      "Expense Claim Cards Error:",
      e
    );
  }


  try {
    renderFooter();
  } catch (e) {
    console.error(
      "Expense Claim Footer Error:",
      e
    );
  }

})();

