  /* =========================================================
     14. ROUTING
  ========================================================= */

  function openRoute(name) {

    if (
      !window.frappe ||
      typeof frappe.set_route !==
        "function"
    )
      return;


    if (
      reportNames.has(name)
    ) {

      frappe.set_route(
        "query-report",
        name
      );

      return;

    }


    if (
      singleDocs.has(name)
    ) {

      frappe.set_route(
        "Form",
        name
      );

      return;

    }


    if (
      treeDocs.has(name)
    ) {

      frappe.set_route(
        "Tree",
        name
      );

      return;

    }


    frappe.set_route(
      "List",
      name
    );

  }


  /* =========================================================
     15. RENDER ACCOUNTING CYCLE
  ========================================================= */

  function renderAccountingCycle() {

    if (!accountingCycle)
      return;


    const title =
      isArabic
        ? "دورة المحاسبة"
        : "Accounting Cycle";


    accountingCycle.innerHTML = `

      <section class="erp-cycle-container">

        <h2
          class="
            erp-section-title
            erp-cycle-title
          "
        >
          ${escapeHtml(title)}
        </h2>


        <div
          class="erp-cycle-grid"
          style="
            grid-template-columns:
            repeat(
              ${accountingCycleCards.length},
              minmax(0, 1fr)
            );
          "
        >

          ${accountingCycleCards

            .map(
              (card, index) => {

                const cardTitle =
                  isArabic
                    ? card.labelAr
                    : card.labelEn;


                const description =
                  isArabic
                    ? card.descriptionAr
                    : card.descriptionEn;


                const arrow =
                  index <
                  accountingCycleCards.length - 1

                    ? `

                      <span
                        class="erp-cycle-arrow"
                        aria-hidden="true"
                      >
                        ${
                          isArabic
                            ? "←"
                            : "→"
                        }
                      </span>

                    `

                    : "";


                return `

                  <div class="erp-cycle-item">

                    <button
                      type="button"
                      class="
                        erp-cycle-card
                        cycle-tone-${(index % 4) + 1}
                      "
                      data-cycle-index="${index}"
                    >

                      <span
                        class="erp-cycle-number"
                      >
                        ${card.step}
                      </span>


                      <span
                        class="erp-cycle-card-title"
                      >
                        ${escapeHtml(cardTitle)}
                      </span>


                      <span
                        class="erp-cycle-description"
                      >
                        ${escapeHtml(description)}
                      </span>

                    </button>


                    ${arrow}

                  </div>

                `;

              }
            )

            .join("")}

        </div>

      </section>

    `;


    accountingCycle.addEventListener(

      "click",

      event => {

        const element =
          event.target.closest(
            "[data-cycle-index]"
          );


        if (!element)
          return;


        const card =
          accountingCycleCards[
            Number(
              element.dataset.cycleIndex
            )
          ];


        if (!card)
          return;


        /* دليل الحسابات */

        if (
          card.action === "tree"
        ) {

          frappe.set_route(
            "Tree",
            card.doctype
          );

          return;

        }


        /* مستند جديد */

        if (
          card.action === "new"
        ) {

          frappe.new_doc(
            card.doctype,
            card.defaults || {}
          );

          return;

        }


        /* اختيار فاتورة */

        if (
          card.action ===
          "invoice-selector"
        ) {

          showInvoiceSelector();

          return;

        }


        /* Route مباشر */

        if (
          card.action === "route"
        ) {

          try {

            frappe.set_route(
              ...card.route
            );

          }

          catch (e) {

            if (
              card.fallbackDoctype
            ) {

              openRoute(
                card.fallbackDoctype
              );

            }

          }

        }

      }

    );

  }


