                          : card.labelEn
                      )}

                    </span>

                  </div>

                </div>

              `
            )

            .join("")}

        </div>

      </section>

    `;


    statsCards.forEach(card => {

      card
        .fetch()
        .then(value => {

          const element =
            statsSection.querySelector(
              `[data-stat-id="${card.id}"]`
            );


          if (!element)
            return;


          if (card.isCurrency) {

            element.textContent =
              `${formatCurrency(value)} ${
                isArabic
                  ? "ر.س"
                  : "SAR"
              }`;

          }

          else {

            element.textContent =
              formatNumber(value);

          }

        });

    });

  }


