    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    700 !important;
}


.erp-footer-link {
  color:
    var(--brand-primary) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600 !important;

  text-decoration: none;

  transition:
    color 0.18s ease;
}


.erp-footer-link:hover {
  color:
    var(--brand-secondary) !important;

  text-decoration:
    underline;
}


.erp-footer-sep {
  color:
    var(--brand-border-strong) !important;

  font-size: 20px;

  font-weight: 300;

  line-height: 1;
}


/* =========================================================
   26. MODAL OVERLAY
========================================================= */

.erp-modal-overlay {
  position: fixed;

  inset: 0;

  z-index:
    99999 !important;

  display: flex;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background:
    rgba(12, 27, 54, 0) !important;

  transition:
    background 0.28s ease;
}


.erp-modal-overlay.is-visible {
  background:
    rgba(12, 27, 54, 0.52) !important;
}


/* =========================================================
   27. MODAL BOX
========================================================= */

.erp-modal-box {
  position: relative;

  width: 100%;

  max-width: 480px;
  max-height: 85vh;

  padding:
    28px 24px;

  overflow-y: auto;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  background:
    #ffffff !important;

  box-shadow:
    0 24px 64px rgba(12, 27, 54, 0.28) !important;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.97);

  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}


.erp-modal-overlay.is-visible
.erp-modal-box {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}


/* =========================================================
   28. MODAL CLOSE
========================================================= */

.erp-modal-close {
  position: absolute;

  top: 12px;

  display: flex;

  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: 0;

  border-radius: 8px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size: 15px;

  cursor: pointer;
}


[dir="rtl"]
.erp-modal-close {
  left: 12px;
}


[dir="ltr"]
.erp-modal-close {
  right: 12px;
}


/* =========================================================
   29. MODAL CONTENT
========================================================= */

.erp-modal-header {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-bottom: 15px;
}


.erp-modal-icon {
  font-size: 28px;

  line-height: 1;
}


.erp-modal-title {
  margin: 0;

  color:
    var(--brand-text) !important;

  font-size: 18px;

  font-weight: 800;
}


.erp-modal-summary {
  margin:
    0 0 16px;

  color:
    var(--brand-text) !important;

  font-size: 13.5px;

  line-height: 1.75;
}


/* =========================================================
   30. MODAL STEP BUTTON
========================================================= */

.erp-modal-toggle-steps {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    8px 16px;

  border:
    1px solid var(--brand-primary);

  border-radius: 9px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 12.5px;

  font-weight: 700;

  cursor: pointer;
}


.erp-modal-toggle-steps:hover {
  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   31. MODAL STEPS
========================================================= */

.erp-modal-steps {
  max-height: 0;

  overflow: hidden;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {
  max-height: 500px;

  opacity: 1;

  margin-top: 15px;
}


.erp-modal-steps-list {
  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {
  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

