  line-height: 1.65;
}


.erp-modal-steps-list li:last-child {
  border-bottom: 0;
}


.erp-modal-steps-list li::before {
  content:
    counter(step-counter);

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  margin-inline-end: 9px;

  border-radius: 50%;

  background:
    var(--brand-primary);

  color:
    #ffffff;

  font-size: 10px;

  font-weight: 800;
}


/* =========================================================
   32. DARK MODE
========================================================= */

[data-theme="dark"]
.erp-dashboard-wrapper,

html[data-theme="dark"]
.erp-dashboard-wrapper {

