  direction: rtl;
  text-align: right;
}


/* =========================================================
   BACKGROUND
   صورة واحدة في الخلفية بدون تكرار
========================================================= */

.erp-dashboard-bg {
    position: absolute !important;

    top: 50px;
    left: 50%;

    /* حجم الصورة */
